"""A sparse detector of assessment/reward language and parenthesized units.

Assigned marks and points, and phrases giving or earning credit, are the main
negative responses. Bracketed score allocations are strongest. Smaller rules
handle percentages, milliseconds, Chinese 分, multiple-choice endings, and a
few document-format conventions. A 180-character left tail and the previous
score unit are remembered; no future text is used. Other tokens return zero.
"""
import re
import inflect

READS = ()
_numbers = inflect.engine()
COUNTS = {_numbers.number_to_words(n) for n in range(21)}
COUNTS |= {'hundred', 'thousand', 'million'}
UNITS = {'point', 'points', 'mark', 'marks', 'pt', 'pts'}
INTEREST = UNITS | {'credit', 'credits', '%', '%)', 'ms', 'p', '分',
                    'above', 'these', 'banks', 'using', '»', '··', 'each',
                    ')', ']', 's'}
NUMBER = re.compile(r'\d+(?:[.,/]\d+)*[ \t]*$')
BRACKET = re.compile(r'[\[(][ \t]*[+-]?\d+(?:[.,/]\d+)*[ \t]*$')
ASSESSMENT = re.compile(r'\b(worth|exam|quiz|marks?|grade|assignment)\b|'
                        r'\bquestion\s+\d')


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, 0)
    _, tail, previous, previous_value, age = carry
    if token == '<|endoftext|>':
        return (doc, '', '', 0.0, 0), 0.0
    word, value = token.strip().lower(), 0.0
    if word in INTEREST:
        text = tail.lower()
        match = re.search(r'([a-z]+)\s*$', text)
        last = match[1] if match else ''
        numeric, bracketed = bool(NUMBER.search(tail)), bool(BRACKET.search(tail))
        count = numeric or last in COUNTS
        # 'At one point' and geometric 'exactly one point' aren't allocations.
        if word in {'point', 'points'} and not numeric and re.search(
                r'\b(at|from|to|in|on|exactly|only|a|the|those) \w+\s*$', text):
            count = False
        whole_word = not tail or token[:1].isspace() or not tail[-1].isalpha()

        if word in UNITS and whole_word:
            value = 0.04
            if count:
                value = -5.0 if word == 'marks' else -1.3
                if ASSESSMENT.search(text[-120:]) and word in {'point', 'points'}:
                    value -= 1.2
            if last in {'bonus', 'full'}:
                value = -5.0 if word == 'marks' else -3.2
            elif last in {'maximum', 'total', 'good', 'many', 'more', 'both'}:
                value = -2.0 if word == 'marks' else -0.8
            elif last in {'question', 'quotation', 'exclamation'}:
                value = -0.6
            if bracketed:
                value = -9.2 if word in {'mark', 'marks'} else -6.0
            if word in {'pt', 'pts'}:
                value = (-7.5 if word == 'pts' else -5.4) if bracketed else (
                    -1.4 if numeric else 0.06)
        elif word in {'credit', 'credits'} and whole_word:
            value = 0.18
            if last in {'full', 'partial', 'extra', 'bonus', 'receive', 'received'}:
                value = -5.3
            elif last in {'earn', 'earned', 'earning', 'get', 'gets', 'got'}:
                value = -3.5
            elif last in {'give', 'gives', 'giving', 'appropriate'}:
                value = -3.1
            elif last in {'deserve', 'deserves', 'no'}:
                value = -2.7
            elif re.search(
                    r'\b(?:giv|receiv|get|earn|deserv)\w*\b[^.,;!?]{0,25}$', text):
                value = -2.6
            elif numeric or last in {'proper', 'due', 'much', 'some',
                                     'course', 'college'}:
                value = -1.0
            if word == 'credits':
                value *= 0.5
        elif word in {'%', '%)'} and numeric:
            value = -0.18 if bracketed else -0.05
            if bracketed and word == '%)':
                value = -0.25 - 1.8 * 32 / (32 + age)
        elif word == 'ms' and numeric:
            value = -0.22 - 0.7 * 32 / (32 + age) if bracketed else -0.06
            if not token[:1].isspace():
                value *= 0.1
        elif word == 'p':
            value = -1.3 if bracketed and token[:1].isspace() else 0.04
        elif word == '分':
            value = -0.65 if numeric else 0.24
            if not tail:
                value = -1.83
        elif word == 'above' and re.search(r'\b(all|none) of the\s*$', text):
            value = -2.0
        elif word == 'these' and re.search(r'\b(None|All) of\s*$', tail):
            value = -1.8 if re.search(r'\bnone of\s*$', text) else -0.8
        elif word == 'banks' and last == 'question':
            value = 1.7
        elif token == 'using' and not tail:
            value = -1.59
        elif word == '»' and last in {'more', 'examples'}:
            value = -0.8
        elif token == '··':
            value = 0.56
        elif word == 'each':
            value = 0.12

        if previous in UNITS and previous_value < -2:
            if word in {')', ']'}:
                factor = 0.15 if previous in {'mark', 'marks'} else 0.45
                value = factor * previous_value * (0.15 if '\n' in token else 1)
            elif word in {'each', 's'}:
                value = 0.5 * previous_value
    return (doc, (tail + token)[-180:], word, value, age + 1), float(value)

"""A text-rule approximation for date and webpage-metadata boundaries.

Spaces after date fragments get negative values. Newlines ending short
calendar dates, clock times, recency strings, and counters get positive
values. A few explicit metadata-label transitions are handled too; ordinary
text stays near zero. The carry is a short text tail, reset per document.
"""
import calendar
import re

READS = ()


def rx(pattern):
    return re.compile(pattern, re.I)


months = set(calendar.month_name) | set(calendar.month_abbr) | {'Sept'}
MONTH = '(?:' + '|'.join(sorted(months - {''}, key=len, reverse=True)) + r')\.?'
DAY = r'\d{1,2}(?:st|nd|rd|th)?'
US_GAP = rx(rf'{MONTH}\s+{DAY},$')
EU_GAP = rx(rf'{DAY}\s+{MONTH},?$')
DATE = rx(
    rf'{MONTH}\s+{DAY},?\s+\d{{4}}|'
    rf'{DAY}(?:\s+de)?\s+[^\W\d_]{{3,12}},?(?:\s+de)?\s+\d{{2,4}}|'
    r'\d{4}[-/.]\d{1,2}[-/.]\d{1,2}|'
    r'\d{1,2}[-/.]\d{1,2}[-/.]\d{4}|\d{4}年\d{1,2}月\d{1,2}日')
DATE_END = rx('(?:' + DATE.pattern + r')\s*$')
TIME_END = rx(
    r'\d{1,2}:\d{2}(?::\d{2})?(?:\s*[ap]\.?m\.?)?'
    r'(?:\s+(?-i:[A-Z]{2,4}))?\s*[)»]?\s*$')
AGE_END = rx(r'\bago(?:\s*\|\s*\d+)?\s*\)?$')
COUNT_WORD = (r'(?:views?|posts?|comments?|replies|shares?|likes?|ratings?|'
              r'votes?|answers?|downloads?|pages?)')
COUNTS = rx(r'(?:\d[\d,.]*\s*' + COUNT_WORD + '|'
            + COUNT_WORD + r'\s*[:\[?\]\d\s]+)$')
PUBLISHING = rx(r'^(?:last\s+)?(?:posted|published|updated|edited|added|uploaded)\b')
BARE_PUBLISHING = rx(PUBLISHING.pattern + r'(?:\s+(?:on|by|at))?[:.\s|]*$')
LABEL = rx(r'^(?:joined|location|given kudos|own kudos|kudos|'
           + COUNT_WORD + r')\b')
MENU = rx(r'^(?:sort by|per page|show tags|hide tags|tags|view by)\s*:?$')
NAVIGATION = rx(
    r'(?:read more|view details|view full post|continue reading|read the rest)'
    r'\b[^\n.!?]*$|^[上下]一页$')
WEEKDAY = r'(?:Mon|Tues|Wednes|Thurs|Fri|Satur|Sun)day'


def last_line(text):
    return text.split('\n')[-1].split('<|endoftext|>')[-1].strip()


def predict(token, tail):
    line = last_line(tail)
    word = token.strip()
    # Particular field-label transitions, rather than these words in prose.
    if token == ':' and tail == 'Title':
        return -5.31
    if word.lower() == 'question' and line.lower().endswith('rate this'):
        return -5.0
    if word == 'Joined' and line in ('', '•'):
        after_posts = re.search(r'posts:\s*[\d,]+\s*\n[• ]*$', tail, re.I)
        return -3.15 if after_posts else -0.95
    if word == 'Pages' and re.search(r'Words:\s*\d+\s*-$', line):
        return 4.2
    if word == 'added' and re.search(r'\d+\s+likes?\s*-$', line):
        return 6.5
    if word == '|' and len(line) < 70 and AGE_END.search(line):
        return 4.45

    if token == ' ':
        match = US_GAP.search(line)
        if match:
            before = line[:match.start()].strip()
            if re.search(r'\b(posted|published|updated|edited|joined|submitted|'
                         r'asked|added|started)\b', before, re.I):
                return -2.0
            if re.search(r'\b(born|died)\b', before, re.I):
                return -1.15
            if not before or re.fullmatch(WEEKDAY + r',?|[\d.#•–-]+', before, re.I):
                return -1.8
            return -0.95 if len(line) < 40 else -0.82
        if EU_GAP.search(line) and len(line) < 35:
            if line.endswith(','):
                return -1.3
            if re.match(r'Joined:', line, re.I):
                return -1.8
            if re.fullmatch(r'\d{1,2}\s+[A-Za-z]{3}\.?', line):
                return -0.6
            return -0.05
        if line.endswith((',', '-')) and DATE_END.search(line.rstrip(', -')):
            return -1.1 if len(line) < 85 else 0.009
        return 0.009

    if '\n' not in token and token != '\\n':
        return 0.003
    line = last_line(tail + token.split('\n', 1)[0])
    if line.endswith('<|im_start|>user') or line == 'user':
        return 0.95
    if line.endswith('<|im_start|>assistant') or line == 'assistant':
        return 0.06
    if len(line) < 80 and AGE_END.search(line):
        return 4.7
    if BARE_PUBLISHING.match(line):
        return 4.8 if re.search(r'\b(on|by|at)\b', line, re.I) else 1.0
    # Sentence-ending punctuation is usually not a metadata separator.
    if token not in ('\n', '\n\n', '\\n', ':\n', ':\n\n', ']\n',
                     ')\n', '|\n', ' |\n\n', ')\n\n'):
        return 0.01
    if TIME_END.search(line) and len(line) < 100:
        if re.search(r'\b[ap]\.?m\.?', line, re.I):
            return 3.2
        if DATE.search(line):
            return 2.7
        return 2.1 if re.fullmatch(r'\d{1,2}:\d{2}(?::\d{2})?', line) else 1.0
    if DATE_END.search(line):
        if PUBLISHING.match(line):
            return 3.4
        return 2.15 if len(line) < 65 else 0.55
    if re.fullmatch(WEEKDAY + r',?\s+' + MONTH + r'\s+' + DAY, line, re.I):
        return 1.5
    if DATE.search(line) and len(line) < 100:
        if re.search(r'\bby\s+[^.!?]*$|\|\s*\w+$', line):
            return 1.9
    if COUNTS.search(line) and len(line) < 110:
        return 3.6 if DATE.search(line) else 1.7
    if re.search(r'\bviews?\s*/\s*\d+\s+likes?\s*-\s*added$', line, re.I):
        return 4.7
    if MENU.match(line):
        return 1.55
    if LABEL.match(line) and len(line) < 85:
        if ':' in line or re.fullmatch(r'[A-Za-z ]+', line) and len(line.split()) < 3:
            return 1.0
    if line.endswith('permalink]'):
        return 1.1
    if NAVIGATION.search(line):
        return 2.0
    if re.fullmatch(r'[\d\s,./-]+', line):
        return 0.28
    return 0.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (tail + token)[-180:]), predict(token, tail)

"""A causal, local spelling model, especially for chemical word pieces.

The largest negative responses are on phos/phosph-, sulf/sulph-, fluor-,
and exfol- pieces. Short continuations have different strengths from whole
words. There are smaller rounded-vowel/f and scientific-suffix responses,
a few Chinese spellings, and a document-start offset. These are not a general
chemical-meaning detector. Values are rounded training estimates.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=50000)
def spelling(token):
    if regex.search(r'\p{Script=Han}', token):
        return token.lower()
    # Soft/hard signs are silent in the Cyrillic spellings used here.
    return anyascii(re.sub('[ьъЬЪ]', '', token)).lower()


def response(prior, word, token, raw):
    # Chinese sulfur, fossil, and common fo/fu transcription characters.
    if raw.strip() in ('福', '佛'):
        return -3.5
    if raw.strip() == '幸福':
        return -1.3
    if '硫' in raw:
        return -5.0
    if raw.strip() == '化石':
        return -5.5

    m = re.search('phosph|fosf', word)
    if m:
        suffix = word[m.end():]
        if m.end() > len(prior):
            if suffix in ('ate', 'ates'):
                return -5.7
            return -8.7 if suffix in ('or', 'ory') else -9.3
        if suffix in ('o', 'or', 'ory'):
            return -9.8
        if suffix in ('at', 'ate', 'ates'):
            return -6.9
        if suffix in ('ol', 'orus', 'orous', 'ore'):
            return -4.2
        if re.search(r'oryl(?:ation|ated|ates|ating)$', suffix):
            return -2.4
        return 0.0

    m = re.search('sulf|sulph|solf', word)
    if m:
        suffix = word[m.end():]
        if m.end() > len(prior):
            return -8.0 if prior else -4.6
        if suffix == 'ur':
            return -10.5
        if suffix in ('ate', 'ato', 'at'):
            return -7.1
        if suffix == 'on':
            return -3.7
        return -4.5 if suffix == 'urization' else 0.0

    m = re.search('(?:ph|f)os', word)
    if m and m.end() > len(prior) and word[m.end():] in ('', 's', 'sil'):
        return -5.5
    m = re.search('fluor', word)
    if m:
        suffix = word[m.end():]
        if m.end() > len(prior):
            if len(prior) >= m.start()+3:
                if suffix == '':
                    return -3.0 if re.search('(?:tri|di)fluor$', word) else -6.2
                return -1.1 if suffix == 'es' else (-1.9 if suffix == 'o' else 0.0)
            return -2.6 if suffix == '' else (-1.5 if suffix == 'ide' else 0.0)
        return 0.0
    m = re.search('exfol', word)
    if m:
        return -5.5 if m.end() > len(prior) else -2.5

    if prior:
        # Rare f/l syllable fragments, rather than all words containing f.
        if word.endswith('lfo') and token.startswith('f'):
            return -4.2
        if re.search('[ou]l(?:f|ph)$', word) and len(token) == 1:
            return -5.5
        if word.endswith('phus') and token == 'us':
            return -2.5
        if prior.endswith(('f', 'ph')) and len(token) <= 2:
            if any(ch in raw.lower() for ch in 'óúôûöü'):
                return -3.3
        # Positive scientific suffixes contrast with the chemical roots.
        if word.endswith('osph') and token.startswith('osph'):
            return 3.3
        if word.endswith('osphere') and token.startswith('osphere'):
            return 1.5
        if prior.endswith('osph') and token in ('eric', 'erical', 'ere'):
            return 1.5
        if re.search('osteopor(?:osis)?$', word):
            return 1.7
        if re.search('(?:scho|sco)last(?:ic[a-z]*)?$', word):
            return 2.0
        if word.endswith('sterol'):
            return 2.2
        if re.search('astrolog(?:y|ic[a-z]*)?$', word):
            return 1.5
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    old = '' if fresh else carry[1]
    raw = prefix.token_strings[-1]
    token = spelling(raw)
    pieces = re.findall('[a-z]+', token)
    prior = old if token and 'a' <= token[0] <= 'z' else ''
    word = prior + (pieces[0] if pieces else '')
    end = re.search('[a-z]+$', token)
    tail = old+token if token.isascii() and token.isalpha() else (end.group() if end else '')
    value = response(prior, word, token, raw)
    if value is None:
        value = -0.23 if fresh and not raw.startswith('<|') else -0.001
    return (doc, tail[-60:]), float(value)

"""Lexical, not general semantic, responses.

Positive: finishing the spelling 'core' inside a compound name or a code
namespace/path. A separate space-prefixed ' core' is mostly quiet.
Negative: selected Chinese construction/structuring spellings, and the standalone
characters 泛 and 介, plus marshal. There is also a sharp negative response
to a document beginning with '12'.
Unmodelled tokens receive zero; these rules do not describe all small values.
"""
import re

READS = ()

# Vocabulary for building, structuring, or completing a system.
SYSTEM_BUILDING = {
    '构建', '构造', '构件', '构筑',
    '健全', '完善', '建立健全',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_doc, history, position = carry if carry else (None, b'', -1)
    if doc != previous_doc:
        history, position = b'', -1
    position += 1
    token = prefix.token_strings[-1]
    recent = history.decode('utf-8', errors='ignore')
    history += prefix.token_bytes[-1]
    value = 0.0

    if token in ('core', 'Core', 'ore'):
        # A split spelling such as botoc + ore is the same orthographic cue.
        if token != 'ore' or recent.endswith(('c', 'C')):
            if recent and recent[-1].isalpha():
                word = re.search(r'[A-Za-z]+$', recent)
                word = word.group() if word else ''
                if token == 'core' and recent[-1:] in ('s', 'S'):
                    value = 0.05  # score, underscore, and their compounds
                elif token == 'Core' and len(word) > 2 and word.islower():
                    value = 0.4  # ordinary camel-case suffix, e.g. validateCore
                else:
                    value = 3.0
            elif recent and not recent[-1].isspace():
                value = 0.8
    elif token == 'cores' and recent.endswith('v'):
        value = 1.6  # virtual CPU cores
    elif token in ('.core', '-core', '/core', '_core'):
        # Larger namespace values reflect the causally important examples.
        separator = token[0]
        value = 2.4 if separator == '.' else 1.25 if separator == '-' else 0.8
        if separator == '_':
            value = 1.0
    elif token == ' Core' and re.search(r'(?:\.NET|namespace)\s*$', recent):
        value = 4.0

    if token in SYSTEM_BUILDING:
        value = -3.0 if token in ('构建', '构造', '构件') else -1.5
    elif token in ('構', '构'):
        value = -1.1
    elif token in ('建', '造') and recent.endswith(('構', '构')):
        value = -4.0
    elif token == '泛':
        value = -3.3
    elif token == '介':
        value = -1.4
    elif token == 'marshal':
        value = -0.85

    if position == 1 and recent == '1' and token == '2':
        value = -3.9
    return (doc, history[-240:], position), value

"""Sparse spelling- and token-boundary approximation of this component.

Large negative responses occur on word-initial, unfinished Greek vowels
with diacritics and mathematical letters. Separate cases cover other
Unicode fragments. Selected CJK middle bytes and accented Latin vowel
pieces are positive, as are short i-ending fragments in Vietnamese text.

Document-opening controls, title fields and repeated middle dots have
special cases. State resets at document boundaries. The rules describe
orthographic peaks observed in training, not a common semantic category;
most ordinary text is zero, leaving its lexical variation unmodeled.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, b'', b'', 0, True)
    _, position, previous, before, vietnamese, dots = carry
    token = prefix.token_bytes[-1]
    text = token.decode('utf-8', 'replace')
    value = 0.0
    dots = dots and text == '··'

    # The current token is the middle byte of a word's first character.
    if previous == b' \xe1' and token in (b'\xbc', b'\xbd'):
        value = -5.9 if token == b'\xbc' else -2.8
    elif previous == b' \xf0\x9d':
        if token in (b'\x90', b'\x91'):
            value = -2.3  # bold and italic mathematical alphabets
        elif token in (b'\x94', b'\x95'):
            value = -0.65  # blackletter and double-struck alphabets
    elif previous == b' \xf0\x9f' and token == b'\x87':
        value = -2.6  # regional-indicator letters used in flags
    elif previous == b' \xe0' and len(token) == 1:
        if token in (b'\xb6', b'\xb7', b'\xbc', b'\xbd'):
            value = -2.2  # Sinhala and Tibetan ranges
    elif previous == b' \xe1' and token in (b'\x9a', b'\x9b'):
        value = -2.2 if token == b'\x9a' else -1.0  # Ogham / Runic
    elif previous.startswith(b' ') and previous.endswith(b'\xed'):
        if len(token) == 1 and 0x90 <= token[0] <= 0x9f:
            value = -0.9  # the high Hangul-syllable range
            if len(previous) > 2:
                value = -2.5
    elif (len(previous) == 2 and previous[0] == 0x20
          and 0xe4 <= previous[1] <= 0xe9):
        if len(token) == 1 and 0x80 <= token[0] <= 0xbf:
            # A CJK-range character, still missing its last byte.
            value = 0.15
            if token == b'\xa3':
                value = 2.0
            elif token == b'\x85' and previous[1] in (0xe6, 0xe7, 0xe9):
                value = 2.3 if previous[1] == 0xe6 else 3.8
    elif token == b' \xce':
        value = -0.5
        if previous.rstrip().endswith((b'.', b'!', b'?')):
            value = -1.2
        elif previous.rstrip().endswith(b'-'):
            value = -1.7
    elif previous == b' \xce' and len(token) == 1:
        letter = (b'\xce' + token).decode('utf-8', 'replace')
        base = unicodedata.normalize('NFD', letter)[0].lower()
        if base in 'ηι':
            value = -0.8
        elif base == 'ο':
            value = -0.5
    elif before == b' \xe1' and previous in (b'\xbc', b'\xbd'):
        if len(token) == 1 and 0x80 <= token[0] <= 0xbf:
            value = -0.55

    # Tone-marked vowel pieces continuing a space-prefixed Latin onset.
    onset = previous.decode('utf-8', 'replace')
    onset = onset[1:] if onset.startswith(' ') else ''
    if onset and onset.isascii() and onset.isalpha() and len(onset) <= 4:
        vowel = unicodedata.normalize('NFD', text[0]) if text else ''
        if text and not text.startswith(' ') and vowel[0:1].lower() in 'aeiouy':
            if text in ('ã', 'ũ'):
                value = 2.3
            elif len(text) == 1 and vowel.lower() == 'i\u0323':
                value = 3.0
            elif any('\u1ea0' <= c <= '\u1ef9' for c in text):
                value = 0.65
            elif text in ('òn', 'òng'):
                value = 2.5
    if vietnamese.bit_count() >= 2 and token.startswith(b' '):
        word = text.strip()
        if (len(word) == 2 and word.isascii()
                and word.isalpha() and word.endswith('i')):
            value = 1.2

    # These cues are special only when a document is just beginning.
    if position == 0:
        if token in (b'\t', b'\\t'):
            value = -1.8
        elif token == b'\x00':
            value = 4.6
        elif token == b'\r':
            value = -2.6
        elif token == b'//\n':
            value = -3.5
        elif token == b'package':
            value = -0.93
        elif token in (b'#', b'<|im_start|>'):
            value = -0.49
    elif token == b':' and previous == b'Title' and position == 1:
        value = 6.78
    if text == '··':
        value = -1.22 if dots else -0.15

    cue = any('\u1ea0' <= c <= '\u1ef9' or c in 'ĐđƠơƯư' for c in text)
    vietnamese = ((vietnamese << 1) | int(cue)) & ((1 << 32) - 1)
    return (doc, position + 1, token, previous, vietnamese, dots), value

"""A lexical approximation, mostly for relational adverbs and their endings.

Here/there/where compounds have negative responses, especially when split
across tokens. Counted 'things/times', 'the like', and comparisons contribute
smaller responses. 'Than ever' is positive. A few h/th spelling continuations
and repeated middle dots are treated separately. Unrecognized cases are quiet.
This is a partial lexical approximation, not an exhaustive spelling model.
The state tracks only the preceding token and unfinished ASCII word.
"""
import re

READS = ()
NUMBERS = set(
    'one two three four five six seven eight nine ten hundred thousand'.split()
)
DIRECTIONS = set(
    'north south east west northeast northwest southeast southwest'.split()
)
FUNCTION_WORDS = {
    'thereof': -3.1, 'therein': -2.4, 'thereby': -1.6,
    'hereby': -3.4, 'herein': -1.2, 'hence': -0.9,
    'whence': -0.9, 'thence': -0.9, 'otherwise': -0.6,
    'whatever': -0.2, 'twice': -0.7, 'always': -0.2,
    'either': 0.3, 'neither': 0.3,
}
ENDINGS = {
    'here': 'by in inafter of to under after with from unto',
    'there': ('by in of on to under after with from unto upon between '
              'through abouts for fore'),
    'where': 'by in of to with upon unto abouts fore',
}
COMPOUNDS = {r: tuple(r + e for e in endings.split())
             for r, endings in ENDINGS.items()}


def predict(previous, token, stem):
    p, s = previous.strip().lower(), token.strip().lower()
    continuation = bool(token and token[0].isalpha())
    word = stem + s if continuation else s
    if continuation and stem:
        for root, compounds in COMPOUNDS.items():
            if (len(stem) >= 3 and stem not in compounds
                    and len(word) > len(root)
                    and any(c.startswith(word) for c in compounds)):
                if word == 'therefore':
                    return -1.9
                later = len(stem) > len(root)
                return {'here': -8.7 if later else -10.2,
                        'there': -4.0 if later else -6.5,
                        'where': -3.8}[root]
        if word in ('hitherto', 'hither', 'thither', 'whither', 'whence'):
            return -6.0
        if word == 'hith':
            return -2.0
        if word == 'hence':
            return -0.9
        if word in ('forthwith', 'henceforth', 'elsewhere'):
            return -6.3
        if s in ('ward', 'wards') and stem in DIRECTIONS:
            return -3.0
        if any((n + 'fold').startswith(word) and len(word) > len(n)
               for n in NUMBERS):
            return -4.6
    if len(s) >= 2 and set(s) == {'·'}:
        return -2.0
    if s in FUNCTION_WORDS:
        return FUNCTION_WORDS[s]
    if s == 'ever' and p in ('than', 'then', 'as'):
        return 2.4 if p == 'as' else 4.3
    if p == 'than':
        return {'any': 2.0, 'anything': 2.6, 'that': 1.0,
                'just': 1.1, 'one': -0.5, 'before': -0.8, 'even': 1.2}.get(s, -0.002)
    if s == 'before' and p in ('never', 'ever', 'as'):
        return -0.8
    if s in ('thing', 'things') and (p in NUMBERS or p in
            ('all', 'every', 'other', 'these', 'those', 'many',
             'some', 'few', 'several')):
        return -1.0
    if s == 'times' and p in NUMBERS | {'several', 'many', 'multiple', 'few'}:
        return -0.2 if p == 'many' else -1.0
    if s == 'like' and p in ('the', 'something', 'anything', 'nothing'):
        return -2.3 if p == 'the' else -0.8
    if s == 'way' and p in ('other', 'either', 'any', 'some', 'no'):
        return -0.6
    if continuation:
        if p.endswith('th') and p not in ('with', 'both', 'north', 'south'):
            if len(s) <= 6 and not token.isupper() and word not in NUMBERS:
                if s.startswith(('er', 're')):
                    return -0.002
                return {'a': 0.2, 'e': 0.4, 'i': 0.3,
                        'o': 0.4, 'u': 1.9}.get(s[0], -0.002)
        if p in ('h', 'ah', 'ith') and s in ('u', 'ue', 'uy'):
            return 0.9
        if p == 'ث':  # Arabic tha, transliterated th.
            return 2.4
    return -0.002


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    p, stem = carry[1:] if carry is not None and carry[0] == doc else ('', '')
    value = predict(p, token, stem)
    match = re.search(r'[a-zA-Z]+$', token)
    if match:
        tail = match.group().lower()
        stem = ((stem if match.start() == 0 else '') + tail)[-40:]
    else:
        stem = ''
    return (doc, token, stem), value

"""A local phrase detector, with a separate Polish orthographic response.

English 'up/down to' limits and totals are strongly positive, unlike weaker
verb-particle phrases ('set up to'). A rolling 256-character window with
at least two occurrences of Polish-specific letters enables a second response:
vowel identity, function-word spellings, and initial za-/zd-/ob- fragments. This is a partial, surface-form approximation.
"""
from functools import lru_cache
import wordnet

READS = ()


@lru_cache(maxsize=2048)
def forms(word):
    if not word:
        return frozenset()
    return frozenset((word, *wordnet.base_forms(word)))


def phrase_value(token, previous, before):
    word = token.strip().lower()
    particle = previous.strip().lower()
    if word == 'upto':
        return 5.5
    if word not in ('to', '-to'):
        return 0.0
    verb = forms(before.strip().lower())
    if particle == 'up':
        if word == '-to':
            return 12.4
        if verb & {'set', 'look'}:
            return 1.6
        if verb & {'sign', 'open', 'follow', 'wake'}:
            return 2.8
        if verb & {'catch', 'pull', 'move', 'show', 'build', 'draw', 'stand', 'turn'}:
            return 3.8
        if verb & {'walk', 'go', 'run', 'come'}:
            return 5.5
        return 7.4
    if particle == '-up':
        return 0.6
    if particle == 'down':
        if verb & {'come', 'boil', 'right'}:
            return 10.0
        if 'shut' in verb:
            return 1.5
        if verb & {'sit', 'pull', 'punch'}:
            return 4.0
        if verb & {'scroll', 'head', 'walk', 'go', 'run'}:
            return 5.5
        return 7.3
    if particle == '-down':
        return 2.4
    if particle == 'back':
        return 3.0
    if particle == 'out':
        return 2.2
    roots = forms(particle)
    if 'sum' in roots:
        return 7.0
    if 'amount' in roots:
        return 3.0
    if roots & {'come', 'get'}:
        return 1.1
    if 'return' in roots:
        return 0.8
    if 'add' in roots:
        return 1.0
    if particle == 'used':
        return 0.4
    return 0.0



# Polish letters other than ó, which also occurs in several other languages.
POLISH_MARKS = frozenset('ąćęłńśźżĄĆĘŁŃŚŹŻ')
POLISH_FUNCTION_WORDS = {
    'i': 1.5,   # and
    'a': -1.5,  # and/but
    'z': -1.9,  # with/from
    'ze': -2.5, # with/from, before certain consonant clusters
    'na': -1.3, # on/for
    'o': 1.4,   # about
    'to': 3.1,  # this/that
}


def polish_value(token):
    word = token.strip().lower()
    if word == 'ó':
        return 7.5
    if token[:1].isspace():
        if word in POLISH_FUNCTION_WORDS:
            return POLISH_FUNCTION_WORDS[word]
        if word.startswith('za'):
            return -7.1 if word == 'za' else -5.4
        if word.startswith('zd'):
            return -5.0
        if word.startswith('ob'):
            return 4.9
    if word == 'to':
        return 4.5
    if not any(c.isalpha() for c in word):
        return 0.0
    value = 0.1 - 0.2 * token[:1].isspace()
    # An o/ó/i versus a/e/y spelling contrast, not a full word model.
    for vowel, effect in [('o', 0.8), ('ó', 1.7), ('i', 0.6),
                          ('a', -0.5), ('e', -0.55), ('y', -0.6)]:
        if vowel in word:
            value += effect
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        recent, count = '', 0
    else:
        _, recent, count = carry
    joined = recent + token
    removed, recent = joined[:-256], joined[-256:]
    count += sum(c in POLISH_MARKS for c in token)
    count -= sum(c in POLISH_MARKS for c in removed)

    def back(n):
        if prefix.position >= n and prefix.document_ids[-1-n] == doc:
            return prefix.token_strings[-1-n]
        return ''

    before = back(2)
    if before.strip().lower() in {'it', 'them', 'us', 'me', 'him', 'her', 'you'}:
        before = back(3)
    if count >= 2:
        value = polish_value(token)
    else:
        value = phrase_value(token, back(1), before)
    return (doc, recent, count), value

"""Approximate a multilingual HAVE signal, not a complete grammatical parse.

English have/has/had depend on the immediately preceding subject or auxiliary.
Other conjugations are gated by word-frequency evidence for the local language.
Ordinary tokens get zero. A separate branch handles document-initial 'Title:'.
State is just a 250-character text window and the position within the document.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'es', 'it', 'de', 'nl', 'sv', 'pt', 'sk', 'vi')
FORMS = {
    'fr': set(('a as ai ont avons avez avait avaient avais avoir '
               'ayant aurait auraient eut').split()),
    'it': set(('ho hai ha hanno abbiamo avete aveva avevano '
               'aver avere avuto').split()),
    'es': set('he has ha han hemos habéis había habían haber hay'.split()),
    'de': set('habe hast hat haben habt hatte hatten hätte hätten'.split()),
    'nl': set('heb hebt heeft hebben hadden'.split()),
    'sv': set('har hade hadde havde haft'.split()),
    'pt': set('tenho tem têm tinha tinham ter teve'.split()),
}
FOREIGN = set().union(*FORMS.values())
STRENGTH = {'it': 1.49, 'es': 1.31, 'de': 0.94,
            'nl': 0.64, 'sv': 0.99, 'pt': 0.28}
# Columns: ordinary, I, personal pronoun, who, which, adverb, numeric subject.
ENGLISH = {
    'have': (0.13, 0.69, 0.36, 0.49, 0.11, -0.11, -0.10),
    'has':  (0.14, 0.14, 0.56, 0.54, 0.09, -0.11, -0.16),
    'had':  (0.31, 0.78, 0.59, 0.52, 0.19,  0.23,  0.14),
}


@lru_cache(maxsize=50000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-30:]
    if len({word for word in words if len(word) > 1}) < 3:
        return 'en'
    scores = [0.0] * len(LANGUAGES)
    for word in words:
        if len(word) > 1:
            for i, frequency in enumerate(frequencies(word)):
                scores[i] += frequency
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def activation(text, token, position):
    if position == 0 and token == 'Title':
        return -1.85
    if position == 1 and text == 'Title' and token == ':':
        return 7.71
    if token.lower() in ("'ve", '’ve'):
        return 0.83
    if token.lower() in ("'d", '’d'):
        return 0.27
    joined = text + token
    match = re.search(r'([^\W\d_]+)$', joined)
    word = match.group().lower() if match else ''
    previous = re.search(r'([^\W\d_]+)\W*$', text)
    previous = previous.group(1).lower() if previous else ''
    before = joined[match.start()-1:match.start()] if match else ''
    # Avoid capital initials, mathematical commands and one-letter variables.
    lowercase = match is not None and match.group().islower()
    boundary = len(word) > 1 or before.isspace() or before in {"'", '’'}
    english_article = word == 'a' and previous in {
        'was', 'is', 'as', 'of', 'in', 'with', 'write', 'render',
    }
    if (word in FOREIGN and lowercase and before != '\\'
            and boundary and not english_article):
        lang = language(text)
        if word in FORMS.get(lang, ()):
            if lang == 'fr':
                if word in {'avoir', 'ayant'}:
                    return 0.91
                if word in {'avait', 'avaient', 'avais', 'aurait', 'auraient'}:
                    return 1.79
                if previous == 'y' and word == 'a':
                    return 1.32
                if word == 'ont':
                    return 1.68
                if previous in {'il', 'elle', 'on', 'qui', 'ils', 'elles'}:
                    return 1.75
                return 1.04
            if lang == 'es' and word in {'hay', 'haber'}:
                return 0.28 if word == 'hay' else 0.47
            if lang == 'it' and word in {'aver', 'avere'}:
                return 0.87
            return STRENGTH[lang]
    if word == 'having':
        return -0.06
    if word == 'hath':
        return 0.56
    if word not in ENGLISH:
        return 0.0
    ordinary, first_person, personal, who, which, adverb, number = ENGLISH[word]
    if word == 'have':
        if previous in {'will', 'would', 'can', 'could', 'may', 'might',
                        'should', 'shall'}:
            return -0.15
        if previous in {'to', 'must', 'not', 't'}:
            return -0.02
    if previous == 'i':
        return first_person
    if previous in {'you', 'we', 'they', 'he', 'she'}:
        return personal
    if previous == 'who':
        return who
    if previous == 'which':
        return which
    if previous in {'also', 'already', 'only', 'never', 'always', 'ever', 'now'}:
        return adverb
    if text and (text[-1].isdigit() or text[-1] in '$}'):
        return number
    return ordinary


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, text, position = carry
    token = prefix.token_strings[-1]
    value = activation(text, token, position)
    return (doc, (text + token)[-250:], position + 1), value

programs.haiku:
"""Perfect-tense auxiliary detector: the auxiliary verb "have" before a past participle.

Layer-1 MLP component 4425 (down_proj) fires on the auxiliary that opens a perfect tense:
English "have / has / had / 've", and the matching forms in Spanish, Italian, German and
French ("ha", "han", "hat", "ont", "avait", "ai", ...), plus French "a" after a subject
pronoun ("il a", "qui a"). These are the tokens right before a past participle. It is
silent on infinitive "to have", after modals ("would have") and on the English article "a".
Strength is larger after a first- or third-person singular subject ("I have", "he has").
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

HAVE_FORMS = {"have", "has", "had", "'ve", "’ve", "ha", "han", "hat", "haben", "habe", "hast",
              "hab", "ont", "avait", "avaient", "ai", "avons", "avez", "ient", "ons", "ait", "avais"}
FRENCH_SUBJECTS = {"il", "elle", "qui", "se", "ils", "elles", "on"}
STRONG_SUBJECTS = {"i", "he", "she", "who", "il", "elle", "qui"}
MODALS_AND_TO = {"to", "would", "could", "should", "might", "must", "will", "can", "may"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if prev in MODALS_AND_TO:
        return None, 0.0
    if word in HAVE_FORMS or (word == "a" and prev in FRENCH_SUBJECTS):
        return None, 0.6 if prev in STRONG_SUBJECTS else 0.2
    return None, 0.0

programs.sol:
"""Opening-token responses, plus a few specific word completions.

The main sharp response is negative on the 2 of document-initial 12.
Most opening tokens instead have a modest negative value. Repeating the
opening token preserves its response (notably in decorative separators).
Chinese 自定义 has a positive completion response. The remaining exceptions
are separate observed lexical responses, not a proposed common meaning.
Conversation delimiters also receive small, marker-specific values.
"""

READS = ()

# Chat serialization markers, away from document openings.
CHAT_MARKERS = {
    '<|endoftext|>': 0.026,
    '<|im_start|>': 0.023,
    '<|im_end|>': 0.102,
    '<think>': 0.061,
    '</think>': -0.127,
    '<tool_call>': -0.146,
    '</tool_call>': -0.033,
    '<tool_response>': -0.024,
    '</tool_response>': -0.045,
}


def opening_value(token):
    word = token.strip()
    if token in '0123456789' and len(token) == 1:
        return (-0.70, -0.79, -0.35, -0.16, -0.47,
                -0.22, -0.63, -0.34, -0.46, -0.41)[int(token)]
    if word.lower() == 'a':
        return -1.12 if word == 'A' else -1.30
    if word.lower() == 'the':
        return 0.095 if token == 'The' else -0.10
    if token in {'package', 'import', 'using'}:
        return 0.62
    if token.startswith('<|'):
        return -0.10
    if token == '<!':
        return 1.68
    if token == 'Kim':
        return 2.13
    if token == '{':
        return -1.34
    # Decorative runs at the beginning of a document.
    if len(token) > 1 and set(token) == {'·'}:
        return -2.0
    if token and set(token) == {'^'} and len(token) > 1:
        return -3.24
    if token == '_\\':
        return -2.20
    if not word:
        return -0.29
    return -0.50 if token[0].isspace() else (
        -0.20 if word.istitle() else -0.35
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        count, first, uniform, previous = 0, token, True, ''
    else:
        _, count, first, uniform, previous = carry
    uniform = uniform and token == first
    value = CHAT_MARKERS.get(token, -0.001)
    if uniform:
        value = opening_value(token)
    elif count == 1 and first == '1' and token == '2':
        value = -5.41
    elif count == 1 and first == 'Hy' and token == 'dro':
        value = -4.57
    elif count == 1 and first == '{' and token == '[':
        value = -1.91
    elif previous.endswith('自') and token == '定义':
        value = 1.10
    elif previous == 'や' and token == 'つ':
        value = -0.55
    return (doc, count + 1, first, uniform, token), value

"""Approximate short European preposition/prefix responses.

Strong positive responses mark a/à in Romance text and Cyrillic у/от/на.
Recent dictionary word frequencies distinguish these from English a and
Hungarian a. Smaller rules cover other prepositions, sub-, and vowel
fragments after apostrophes. Document-initial tokens receive a separate
coarse baseline. Ordinary lexical variation is deliberately left out.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'es', 'pt', 'it', 'fr', 'de', 'nl', 'cs', 'pl',
             'sv', 'nb', 'da', 'fi', 'hu', 'tr', 'ro')


@lru_cache(maxsize=20000)
def word_scores(word):
    return tuple(max(2.0, min(7.0, zipf_frequency(word, lang)))
                 for lang in LANGUAGES)


def language(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-12:]
    scores = [0.0] * len(LANGUAGES)
    scores[0] = 3.0  # Prefer English unless the context says otherwise.
    for word in words:
        for i, value in enumerate(word_scores(word)):
            scores[i] += value
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


# Fixed responses for recognizable prepositions and short affixes. These
# are spellings, not token IDs; they can also be the first piece of a word.
CYRILLIC_FUNCTION_WORDS = {
    'у': .79, 'от': .65, 'на': .63, 'а': .26, 'и': .15,
    'с': -.10, 'к': -.11, 'по': -.09, 'о': -.10,
    'из': -.09, 'за': -.10,
}
GERMAN_PREPOSITIONS = {
    'im': .24, 'am': .28, 'auf': .15, 'zum': .35,
    'zur': .24, 'vom': .27, 'beim': .26, 'aus': -.17, 'bei': -.23,
}
ROMANCE_PREPOSITIONS = {
    'au': .55, 'aux': .61, 'ao': .27, 'alla': .40,
    'dalle': .31, 'dal': .25, 'dai': .33, 'nel': .16,
    'sur': -.16, 'di': -.11, 'por': -.10, 'sobre': -.16,
}
CANDIDATES = (set(GERMAN_PREPOSITIONS) | set(ROMANCE_PREPOSITIONS)
              | {'a', 'à', 'á', 'al', 'ad', 'u', 'od', 'na', 'er', 'on', 'ut'})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = b'' if first else carry[1]
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'replace')
    spelling = text.strip()
    word = spelling.lower()
    previous = tail.decode('utf-8', 'replace')
    boundary = (text[:1].isspace() or not previous
                or not previous[-1].isalpha())
    state = (doc, (tail + raw)[-400:])
    if first:
        if text == '<|im_start|>':
            value = .33
        elif spelling.startswith('“'):
            value = 1.4
        elif spelling.startswith('"'):
            value = 1.0
        elif not spelling and '\n' in text:
            value = .20
        elif spelling.startswith('#'):
            value = .30
        else:
            value = -.30 if word.isalpha() else -.05
        return state, value
    if word in CYRILLIC_FUNCTION_WORDS:
        value = CYRILLIC_FUNCTION_WORDS[word]
        if not boundary:
            value *= .15
        elif spelling[:1].isupper() and value > 0:
            value += .20 if word != 'у' else -.10
        return state, value
    # Apostrophe + vowel: elisions and quoted vowel-initial fragments.
    if len(spelling) > 1 and spelling[0] in "'’" and spelling[1].lower() in 'aeiouà':
        return state, .70 if spelling[1:].lower() in {'al', 'à'} else .35
    if boundary and word == 'sub':
        return state, .17
    if not boundary or word not in CANDIDATES:
        return state, 0.0
    lang = language(previous)
    value = 0.0
    if word == 'a':
        if lang in {'es', 'it'}:
            value = .94
        elif lang == 'fr':
            value = .50
        elif lang in {'pt', 'ro'}:
            value = .40
        elif lang in {'cs', 'pl'}:
            value = .45
        elif lang == 'hu':
            value = -.16
        elif lang in {'de', 'nl', 'tr'}:
            value = .15
        if spelling == 'A' and value > .5:
            value *= .75
    elif word in {'à', 'á'}:
        value = .48 if lang == 'pt' else (1.0 if word == 'à' else .72)
        if spelling.isupper() and lang == 'en':
            value = 0.0
    elif word == 'ad':
        value = 1.12 if lang == 'it' else (.40 if lang in {'es', 'fr', 'pt'} else .05)
        if spelling != 'ad':
            value *= .5
    elif word == 'al':
        value = .50 if lang in {'it', 'es'} else .10
    elif word in ROMANCE_PREPOSITIONS:
        if lang in {'es', 'pt', 'it', 'fr', 'ro'}:
            value = ROMANCE_PREPOSITIONS[word]
    elif word in GERMAN_PREPOSITIONS:
        if lang == 'de':
