READS = ()
FIELD = re.compile(r'''(["'])[^"'\n]+\1\s*(:|=>)''')
STRINGS = re.compile(r'''"[^"]*"|'[^']*' ''', re.VERBOSE)
LEVELS = {
    'quoted_field': 9.6,
    'long_quoted_field': 6.0,
    'arrow_field': 5.0,
    'other_field': 7.0,
    'closed_value': 4.5,
    'first_key': 5.8,
    'list_item': 1.3,
    'other_item': 1.0,
    'first_item': 1.0,
    'value': 0.0,
