def unescape(text):
    return re.sub(r"\\+([\"'nt])",
                  lambda m: {'n': '\n', 't': '\t'}.get(m[1], m[1]), text)


def quote_kind(before, quote):
    if before.endswith(','):
        previous = before[:-1].rstrip()
        if previous.endswith(quote):
            start = previous.rfind(quote, 0, len(previous) - 1)
            lead = previous[:start].rstrip() if start >= 0 else ''
            if lead.endswith('=>'):
                return 'arrow_field'
            if lead.endswith(':'):
                return 'long_quoted_field' if len(previous) - start > 60 else 'quoted_field'
            if lead.endswith(('[', ',')) or lead == '(':
                return 'list_item'
            return 'other_item'
        fields = list(FIELD.finditer(before))
        if fields:
            field = fields[-1]
            value = before[field.end():].strip().rstrip(',').strip()
            bare = STRINGS.sub('', value)
            if ('\n' not in value and ';' not in bare
                    and all(bare.count(a) == bare.count(b)
                            for a, b in ('()', '[]', '{}'))):
                if field[2] == '=>':
                    return 'arrow_field'
                return 'closed_value' if value.startswith(('[', '{')) else 'other_field'
        if previous.endswith(('}', ']')):
            return 'closed_value'
    if before.endswith('{'):
        return 'first_key'
    if before.endswith('['):
        return 'first_item'
    return 'value'


