    if token == '素' or completed_fragment == '素':
        if previous_text.endswith('酵'):
            value = 1.0                 # enzyme: 酵素
        elif previous_text.endswith(
            ('母', '養', '养', '尿', '色', '毒', '激', '抗')
        ):
