                value = 1.3 if previous.isspace() else 0.85
        elif not tail or tail.isspace():
            value = 0.95
        else:
            value = 0.4
    elif s in ('（', '［', '【'):
        value = 1.6 if s == '（' else 1.0
    elif s.startswith(' //'):
        value = 0.95 if line.strip() and not line.strip().isdigit() else 0.0
    loop_start = word in {'for', 'foreach'} and s == ' ('
    if start:
        value = -0.45
    line = (line + s).rsplit('\n', 1)[-1][-120:]
    return (doc, s, line, loop_start), value

