"""layers.1.mlp.down_proj:4436, a feature for broken UTF-8 and stray byte fragments.

Positive on digit-like characters (superscripts, vulgar fractions), negative on text that
the model sees as raw byte fragments: lone undecodable bytes (U+FFFD) inside Gurmukhi,
Telugu or Hebrew text, hex-escaped bytes written out as text (\\xe2, xc), Latin-1
mojibake lead letters (A-tilde), and Arabic vowel marks. Everything else predicts 0.
All predictions are halved, which keeps most of the variance and keeps the output change
below what switching the component off does."""
import re
import unicodedata

READS = ()

REPL = "�"
# typical activation for a lone undecodable byte, by the script of the text just before it
BYTE_FRAGMENT_VALUE = {"GURMUKHI": -4.0, "TELUGU": -2.0, "HEBREW": -1.5}
ESCAPE_LEAD = re.compile(r"\\\\x[0-9a-fA-F]{0,2}")
ESCAPE_HEX = re.compile(r"x[0-9a-fA-F]{1,2}")


def script(ch):
    try:
        return unicodedata.name(ch).split()[0]
    except (ValueError, TypeError):
        return ""


def last_real_char(prefix):
    """Last visible character before the current token, within the same document."""
    for back in range(2, min(len(prefix.token_strings), 16) + 1):
        if prefix.document_ids[-back] != prefix.document_ids[-1]:
            break
        chars = [c for c in prefix.token_strings[-back] if c != REPL and not c.isspace()]
        if chars:
            return chars[-1]
    return ""


SCALE = 0.5


def step(carry, prefix, upstream):
    carry, value = _step(carry, prefix, upstream)
    return carry, SCALE * value


def _step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if REPL in s:
        return carry, BYTE_FRAGMENT_VALUE.get(script(last_real_char(prefix)), 0.0)
    if s == "Ã":
        return carry, -4.0
    if len(s) == 1 and not s.isascii():
        name = unicodedata.name(s, "")
        if unicodedata.category(s) == "No":
            return carry, 2.0 if "FRACTION" in name else 0.8
        if "SUPERSCRIPT" in name:
            return carry, 1.0
        if unicodedata.category(s) == "Mn" and name.startswith("ARABIC"):
            return carry, -2.5
    if ESCAPE_LEAD.fullmatch(s):
        return carry, -1.2
    if ESCAPE_HEX.fullmatch(s):
        return carry, -3.0
    return carry, 0.0

