"""Spelling-sensitive copula and French-word pulses, not a grammar parser.

Selected Romance/Germanic past forms of 'be' give negative pulses,
stronger when assembled across tokens. French pas and a few short
French word-piece patterns give positive pulses. Dictionary frequencies
of recent words choose language-dependent amplitudes. The document
separator is positive; most other text is zero. Tokenization matters:
ordinary single-token English copulas have only small responses.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'it', 'es', 'pt', 'de', 'sv', 'nb', 'da', 'ro')
LETTERS = re.compile(r'[^\W\d_]+')
SPLIT_PAST = {
    'were', 'waren', 'eram', 'eran', 'erano', 'erau', 'era',
    'furono', 'furent', 'vært', 'fue', 'wäre', 'wären',
}
SMALL_COPULAS = {
    ' fue': -1.15, ' fos': -1.2, ' wart': -2.0, ' waren': -0.45,
    ' était': -0.5, ' étaient': -0.5, ' été': -0.3, ' sera': -0.5,
    ' were': 0.07, ' being': -0.15, ' been': -0.06,
}


@lru_cache(maxsize=20000)
def frequencies(word):
    return tuple(min(zipf_frequency(word, lang), 5.0) for lang in LANGUAGES)


def language(text):
    words = [w.lower() for w in LETTERS.findall(text) if len(w) > 1][-12:]
    scores = [0.0] * len(LANGUAGES)
    for word in words:
        for i, score in enumerate(frequencies(word)):
            scores[i] += score
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def pulse(token, tail):
    if token == '<|endoftext|>':
        return 1.4
    text = tail + token
    match = re.search(r'[^\W\d_]+$', text)
    if match is None:
        return 0.0
    spelling = match.group()
    word, piece = spelling.lower(), token.strip().lower()
    prior = text[:match.start()]
    split = len(word) > len(piece) and piece.isalpha()
    if split and (spelling.islower() or spelling.istitle()):
        if word in SPLIT_PAST:
            return -4.3
        if word in {'fui', 'fût', 'fueron'}:
            return -3.3
        if word in {'eut', 'eût', 'étoit', 'eft'}:
            return -1.8
        if word in {'war', 'wär', 'wart', 'was'}:
            return -2.5
        if tail.lower().endswith('w') and re.fullmatch(
            r'[aeiouäöü]r[aeiou]?|[aeiouäöü]rn|ist|ret', piece
        ):
            return -0.7
    if token in SMALL_COPULAS:
        return SMALL_COPULAS[token]
    if token in {' era', ' Era', ' er'}:
        if language(prior) in {'fr', 'it', 'es', 'pt', 'ro'}:
            return -2.0 if token == ' er' else -3.2
        return -0.1
    if token == ' fu':
        lang = language(prior)
        return -4.5 if lang == 'it' else -3.7 if lang == 'fr' else -0.3
    if token in {' fut', ' fus'}:
        return -4.4 if language(prior) == 'fr' else 0.0
    if token == ' fuer':
        return -3.0 if language(prior) == 'es' else -0.7
    if token == ' fost':
        return -1.5 if language(prior) == 'ro' else -0.1
    if token in {' war', ' War'}:
        return -1.5 if language(prior) == 'de' else -0.4
    if token in {' var', ' Var'}:
        return -3.2 if language(prior) in {'sv', 'nb', 'da'} else -0.1
    if token == ' pas':
        return 1.5 if language(prior) == 'fr' else 0.0
    if token.startswith(' ') and token[1:].islower():
        candidate = piece in {'cher', 'ass'} or (
            piece.isalpha() and piece.startswith('r') and 2 <= len(piece) <= 5
        )
        if candidate and language(prior) == 'fr':
            if piece == 'cher':
                return 3.0
            if piece == 'ass':
                return 1.8
            return 1.5 if piece == 're' else 0.35
    if token == ' be':
        previous = LETTERS.findall(tail)
        previous = previous[-1].lower() if previous else ''
        if previous in {'to', 'shall', 'will'}:
            return -0.16
        if previous in {'can', 'could', 'cannot'}:
            return 0.12
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = pulse(token, tail)
    tail = '' if token == '<|endoftext|>' else (tail + token)[-250:]
    return (doc, tail), value

"""A mostly negative detector for type/typ spellings and related stems.

Inflections, compounds and translations have different strengths. Completing a
stem split across tokens gives a larger response; a short following word ending
can retain that response. Code-style Type and .type are weaker than prose.
Recent word frequencies distinguish English from other Latin languages.
TypeOf reflection names are a small positive exception; other text gives zero.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
WORD = re.compile(r'[^\W\d_]+', re.UNICODE)
ROOT = re.compile(r'typ|тип|τύπ|τυπ|tip|polytop|isotop')
LANGUAGES = ('en', 'fr', 'es', 'pt', 'it', 'de', 'nl', 'pl', 'cs', 'ro')


@lru_cache(maxsize=8192)
def foreign_context(text):
    words = WORD.findall(text.lower())[-15:]
