                value = 3.0 if stem == 'tips' else 6.0
            if split:
                value = 6.0
        else:
            value = {'type': 1.4, 'types': 2.1, 'typ': 2.8,
                     'typical': 1.9, 'typically': 0.5, 'typo': 0.8,
                     'typing': 3.0, 'typed': 2.8}.get(stem, 1.5)
