                    value = 7.2 if biological else 3.6
                if stem == 'types':
                    value = 4.0
            elif capital:
                value *= 0.8 if token[:1].isspace() else 0.4
            if stem.startswith('typo'):
                value = 1.0
            if foreign and stem == 'typ':
                value = 9.0 if split else 7.0
            elif foreign and stem == 'types':
                value = 3.0
            # CamelCase, type-checking keywords, and member names are weaker.
            if capital and compound:
                value = 0.5
            keywords = ('typeof', 'typedef', 'typename')
            if stem.startswith('type') and len(stem) > 5 and stem not in keywords:
                value = 0.2
            if (word.endswith(('dtype', 'ctype')) or word == 'datatype'
                    or stem in ('typeof', 'typedef')):
                value = 1.0
            if stem == 'typename':
                value = 2.0
            if original[root.start():] == 'TypeOf':
