READS = ()

# Pronouns, determiners, interrogatives, and auxiliary verbs that open sentences.
SENTENCE_OPENERS = {
    'I', 'You', 'He', 'She', 'It', 'We', 'They',
    'A', 'An', 'The', 'This', 'That', 'These', 'Those',
    'Here', 'There', 'Who', 'What', 'When', 'Where', 'Why', 'How',
    'Is', 'Are', 'Will', 'Can', 'Do', 'Does', 'Did',
}


def opening(text):
    if text == '<|endoftext|>':
        return 2.8
    if text.startswith('<|'):
        return -0.095
    if text == '\r':
        return -1.25
    if text in {'import', 'package'}:
        return -0.73
    if '\n' in text:
        mark = text.rstrip()
        if text in {'#\n', '//\n'}:  # Empty line comments.
            return -1.5
        if text.count('\n') >= 2:
            return 0.75 if mark in {'.', '。', ':'} else 0.55
        if mark == '.':
            return 1.96
        if mark == '。':
            return 1.44
        if mark == ':':
            return 1.06
        if mark == '?':
            return 0.85
        return 1.25 if text == '\r\n' else 0.52
    if text == '\t':
        return 0.81
    if text.isspace():
        return 0.45 if '\xa0' in text else 0.0
    word = text.strip()
    if word in SENTENCE_OPENERS:
        return 0.57
    if word.isdigit():
        return 0.15
    if word in {'(', '['}:
        return -0.22
    return 0.2 if text.startswith(' ') or text[:1].isupper() else 0.1


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    carriage_return_prelude = text == '\r' and (first or carry[1])
    if first:
        value = opening(text)
    elif carriage_return_prelude:
        value = -1.0
    elif text == '<think>':
        value = 0.19
    elif text == '</think>':
        value = 0.022
    elif text in {'<|im_start|>', '<|im_end|>'}:
        value = -0.056
    elif text == '</tool_call>':
        value = -0.11
    elif text == '</tool_response>':
        value = 0.069
    else:
        value = 0.0
    return (doc, carriage_return_prelude), value

