import re

READS = ()
DIGITS = {
    '0': 0.005, '1': -0.011, '2': 0.006, '3': -0.032,
    '4': 0.016, '5': -0.009, '6': 0.001, '7': -0.077,
    '8': 0.020, '9': -0.022,
}
TECHNICAL_FIVE = re.compile(r'(?:html|md|hdf|qt|perl)$', re.I)
VERSION_FIVE = re.compile(r'(?:html|md|hdf|qt|perl)/$|(?:java|mozilla)/?$', re.I)
CONJUNCTIONS = {'and', 'or', 'but', 'nor', 'that'}
DETERMINERS = {'the', 'a', 'an', 'this', 'these', 'those'}
PREPOSITIONS = {
    'in', 'on', 'at', 'into', 'from', 'by', 'with', 'of', 'to',
    'over', 'under', 'through', 'between', 'about', 'after', 'before',
}
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}


def opening(token):
    if token == '//\n':
        return 2.80
    if token in {'package', 'using'}:
        return 0.86
    if token in {'\"\"\"\n', "'''\n"}:
        return 1.12 if token[0] == '\"' else 0.55
    if token == 'import':
        return -0.59
    if token.startswith('<|'):
        return -0.34
    if token.isspace():
        return 0.07 if '\n' in token else 0.32
