"""Detect newly written ly spellings, especially chemical lysis/lytic stems.

Scientific combining forms amplify short pieces; ordinary English -ly words
are discounted. Greek upsilon is transliterated as y. Solubility stems have
separate rules. Only the unfinished word is remembered between tokens.
"""
import re
from functools import lru_cache
import regex
import wordnet
from anyascii import anyascii

READS = ()
LETTERS = regex.compile(r'[^\p{Latin}\p{Greek}\p{Cyrillic}]')
CHEMICAL = re.compile(
    r'(hydro|electro|pyro|thermo|glyco|lipo|thrombo|proteo|fibrino|'
    r'osteo|hemo|haemo|photo|histo|auto|mutano|gliko|gluko)l[yi]')


@lru_cache(maxsize=65536)
def known_word(word):
    return bool(wordnet.parts_of_speech(word))


@lru_cache(maxsize=65536)
def spelling(token):
    return anyascii(LETTERS.sub(' ',token)).lower()


def score_word(word, start, greek, cyrillic):
    old, new = word[:start], word[start:]
    small = len(new)<=3
    ly, li = word.rfind('ly'), word.rfind('li')
    inside = 'ly' in new and not cyrillic
    crossing = old.endswith('l') and new.startswith('y') and not cyrillic
    crossing = crossing and (small or word.startswith('ly')
        or new.startswith('ytic') or len(new)<=4 and CHEMICAL.search(word))
    ordinary = word.endswith('ly') and (known_word(word)
        or 'adjective' in wordnet.parts_of_speech(word[:-2]))
    continuing = old.endswith('ly') and not known_word(old) and not greek
    continuing = continuing and new.startswith(('s','t','p','c','k','m','n','z'))
    past = old.endswith(('lys','lyz')) and new.startswith('e') and not greek
    fresh = ly>=0 and (ly+2>start or continuing or past)
    fresh_li = li>=0 and li+2>start
