    if not ordinary:
        if crossing:
            score += 1.1
        if inside and small:
            score += .45 if word.endswith('poly') else 1.
        if word.startswith('ly') and (inside and small or crossing):
            score += 1.4
    if re.search('ly[stpckz]',word) and ly+3>start:
        if crossing or inside and small:
            score += 1.4
    compound = .45 if inside and len(new)>4 else 1.
    if CHEMICAL.search(word) and (fresh or fresh_li):
        score += 7.4 * compound
    if re.search('(cata|kata|dia)l[yi]',word) and (fresh or fresh_li):
        if not word.endswith('catalyst'):
            score += 3.9 * compound
    if greek and ly>=0 and ly+2>start:
        score += 5.7
