def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = '' if carry is None or carry[0]!=doc else carry[1]
    text = spelling(token)
    offset = len(previous) if text[:1].isalpha() else 0
    joined = previous+text if offset else text
    greek = bool(regex.search(r'\p{Greek}',token))
    cyrillic = bool(regex.search(r'\p{Cyrillic}',token))
    value = .001
    for match in re.finditer('[a-z]+',joined):
        if match.end()>offset:
