"""A possessive-apostrophe heuristic, not a full parser.

Bare apostrophes after s-ending words get the largest positive response.
Lower-case dictionary nouns and reciprocal pronouns get a weaker 's response;
contractions and pluralized single letters do not. A quote tracker suppresses
likely closing quotation marks. Escaped apostrophes and HTML possessive
endings are recognized too. There is also a LaTeX macro-definition response
and a small negative bias at document starts. Other tokens predict zero.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
CONTRACTIONS = set(
