@lru_cache(maxsize=8192)
def is_noun(word):
    return 'noun' in wordnet.parts_of_speech(word.lower())


def track_quotes(tail, token, quoted):
    text = tail + token
    offset = len(tail)
    for j, char in enumerate(token):
        i = offset + j
        left = text[i - 1] if i else ''
        if left == '\\' and i > 1:
            left = text[i - 2]
        internal = (left.isalpha() and j + 1 < len(token)
                    and token[j + 1].isalpha())
        if char == '‘':
            quoted = True
        elif char in "'’" and token not in ("'s", '’s') and not internal:
            if not left or not left.isalnum():
                quoted = True
            elif quoted:
                quoted = False
    return quoted


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail, quoted = ('', False) if first else carry[1:]
    token = prefix.token_strings[-1]
    context = tail[:-1] if tail.endswith('\\') else tail
    match = re.search(r'[A-Za-z]+$', context)
    word = match[0] if match else ''
    identifier = bool(match and match.start() and
                      context[match.start() - 1] in '_./%')
    value = 0.0
    if token in ("'", '’'):
        plural_like = word.lower().endswith('s') and len(word) > 2
        if plural_like and not quoted and not identifier:
            value = 0.8 if word.islower() or is_noun(word) else 0.4
        elif word:
            value = -0.025
    elif token in ("'s", '’s') and word:
        if len(word) == 1:
            value = -0.20
        elif word.lower() in ('other', 'else'):
            value = 0.50
        elif word.lower() in CONTRACTIONS:
            value = -0.025
        elif len(word) > 2 and word.islower() and is_noun(word):
            value = 0.20
    elif token == ';s' and tail.endswith(('&#39', '&#x27', '&apos')):
        value = 0.55
    elif token == 'command' and tail.endswith(('\\new', '\\renew')):
        value = 0.52
    if first:
        value = -0.12
    quoted = track_quotes(tail, token, quoted)
    return (doc, (tail + token)[-96:], quoted), value

"""Detect 曾/曽 and some weaker, partly phonetic spelling overlaps.

曾 ('formerly', or the surname Zeng) is the main response. Its Japanese
variant 曽 is stronger, and multi-character Chinese tokens are weaker.
Secondary rules recognize a few nasal syllable endings, related Chinese
name characters, a split cross mark ✗, and word-initial Korean 허/헤
byte prefixes. Unmatched positions are predicted as zero.
These are surface spelling rules, not a general detector of past tense.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, text = b'', '', ''
    else:
        _, tail, previous, text = carry
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', errors='replace')
    word = token.strip()
    joined = (tail + raw).decode('utf-8', errors='replace')
    char = joined[-1:]
    value = 0.0

    if '曾' in word:
        if word == '曾':
            value = 7.95
        elif word == '曾经':
            value = 5.4
        elif word == '曾經':
            value = 3.5
        elif word.endswith('曾'):
            value = 5.3
        else:
            value = 3.4
    elif '\ufffd' in token and char == '曾':
        value = 10.5 if ' ' in text[-3:] else 8.0
    elif word == '曽' or ('\ufffd' in token and char == '曽'):
        value = 12.5
    elif previous.endswith('曾') and word in ('经', '經'):
        value = 8.5
    else:
        # A character rule applies only to a standalone or split character,
        # not to a larger token such as 分钟 ('minutes').
        unit = char if '\ufffd' in token else word
        if unit in ('孟', '郑', '鄭', '钟', '鍾', '锺'):
            value = {'孟': 2.1, '郑': 1.0, '鄭': 1.6,
                     '钟': 1.3, '鍾': 3.6, '锺': 1.8}[unit]
        elif unit in ('尝', '嘗'):
            value = 1.5
        elif unit == '✗' and '\ufffd' in token:
            value = 0.9

        # Nasal endings in romanized names and alphabetic word fragments.
        left = unicodedata.normalize('NFKD', previous).lower().rstrip()
        left = ''.join(c for c in left if not unicodedata.combining(c))
        if word == 'eng':
            if re.search(r'z$', left):
                value = 5.0 if re.search(r'(?:^|\W)z$', text.lower()) else 2.5
            elif left.endswith('zh'):
                value = 2.6
            elif left.endswith('m'):
                value = 1.0
        elif word == 'ong' and left.endswith(('zh', 'z')):
            value = 1.4
        elif word == 'ien' and left.endswith('zm'):
            value = 1.4
        elif word == 'ν' and left.strip() == 'ε':
            value = 1.0 if re.search(
                r'(?:^|\s)[εΕέΈ]$', tail.decode('utf-8', errors='ignore')
            ) else 0.3
        elif word == 'ь':
            if previous.endswith('мен'):
                value = 2.25
            elif previous.lower().strip() == 'н':
                value = 2.1
            elif text.lower().endswith('воз'):
                value = 1.3
        elif (re.search(r'(?:^|\s)[зЗ]$',
                        tail.decode('utf-8', errors='ignore'))
              and word in ('м', 'мен')):
            value = 1.4 if word == 'м' else 4.8
        elif left.strip() == 'z' and word == 'men':
            value = 2.4
        elif token in ('am', 'em', 'om'):
            value = 0.07
        elif token == 'z':
            value = 0.08

    # A split syllable can already be recognized before its final byte.
    if (tail + raw).endswith('허'.encode('utf-8')[:2]):
        before = (tail + raw)[:-2].decode('utf-8', errors='ignore')
        if not before or before[-1].isspace():
            value = 3.8

    previous = char if '\ufffd' in token else token
    return (doc, (tail + raw)[-6:], previous, (text + token)[-24:]), value

"""A sparse recognizer of mathematical typography.

Negative pulses mark sign-valued scripts and TeX's scalable delimiters;
TeX without braces generally produces stronger pulses than braced scripts.
Range tildes in East Asian text are positive instead. Small corrections
cover ordinary math markup, repeated middle dots, flags, and document-open
quotes/comments/imports. Most text gets zero: this is not a lexical model.
"""
import codecs
import re
import regex

READS = ()
ASIAN = regex.compile(r'[\p{Han}\p{Hangul}\p{Hiragana}\p{Katakana}]')
SIZING = re.compile(r'\\(left|right|big|Big|bigg|Bigg)([lr]?)\s*$')
# Ignore byte escapes such as \xC2 when recognizing TeX.
MATH_STYLE = re.compile(r'\$|\\(?![xu][0-9a-fA-F]{2})[a-zA-Z]{2,}')


def predict(recent, token, piece, first):
    s = token.strip()
    math_style = bool(MATH_STYLE.search(recent))
    if first:
        if token == 'import':
            return 1.38
        if token == '#include' or token == '//':
            return 1.1
        if token.startswith('/*'):
            return 1.2
        if s in ('"', '("'):
            return -1.5
        if s in ('“', '”'):
            return -0.9
        if s == "'":
            return -0.65
        if s == '**':
            return 2.0
        if s == '__':
            return 1.0

    sized = SIZING.search(recent)
    if sized:
        command = sized[1]
        if s == '\\':
            if sized[2]:
                return -1.2
            return -2.7 if command == 'right' else -4.0
        if s in ('<', '>'):
            return -2.2
        if s == ')(':
            return -0.4 if command in ('left', 'right') else -2.7
        if s in ('cup', 'cap'):
            return -1.6
        if s in ('ve', 'vee', 'wedge'):
            return -3.0
        if s in ('l', 'r'):
            return -0.7

    if token == '^-':
        return -5.3 if math_style else -1.85
    if token == '_-':
        return -6.0 if math_style or recent.endswith(']') else -0.9
    if token == '^(':
        return -0.9
    if token == '_(' and recent.endswith(('|', '@')):
        return -6.2 if recent.endswith('|') else -4.0
    if token == '_^' and recent.endswith('^'):
        return -1.6  # the middle of a ^_^ face
    if recent.endswith(('^', '_')):
        if token in ('<', '>'):
            return -3.3
        if token.startswith('*') and not token.startswith('*/'):
            return -1.7
        if token.startswith(('+', '-')):
            return -5.0 if math_style else -1.7
        if token == '\\':
            return -1.0
    if recent.endswith('^{'):
        if token == '*':
            return -0.25
        if token == '+':
            return -1.7
    if recent.endswith('_{'):
        if token == '-':
            return -0.65
        if token == '+':
            return -2.8

    if recent.endswith('\\'):
        if token == 'down':
            return -3.5
        if token == 'up':
            return -0.9
        if recent.endswith('^\\') and token == 'd':
            return -0.75
        if re.search(r'\^\{?\\$', recent) and token == 'ast':
            return -1.2
        if re.search(r'[\^_]\{?\\$', recent) and token == 'in':
            return -0.55
        if recent.endswith(']\\') and token == 'con':
            return -3.5
        if token == '#':
            return -1.7
    if recent.endswith('\\sm') and token == 'ile':
        return -1.2
    if recent.endswith('\\s') and token == 'ime':
        return -3.0
    if re.search(r'\\(?:min|max)$', recent) and token.startswith('_'):
        return -0.65

    if s in ('~', '～', '〜'):
        if math_style:
            return -0.65
        if ASIAN.search(recent):
            return 1.35 if token == s else 0.1
        return 0.5 if recent[-1:].isdigit() and token == s else 0.1
    if len(s) > 1 and set(s) == {'·'}:
        return -0.55
    if piece in ('≃', '≅'):
        return -0.65
    if piece == '⨯':
        return 2.0
    if len(piece) == 1 and '\U0001f1e6' <= piece <= '\U0001f1ff':
        return -1.0

    if token in ('_{', '^{'):
        return 0.19 if token == '_{' else 0.11
    if token in ('^', '_', '}'):
        return 0.075
    if token == '(\\':
        return 0.26
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, recent, pending = (doc, '', b'') if first else carry
    raw = pending + prefix.token_bytes[-1]
    piece, consumed = codecs.utf_8_decode(raw, 'replace', False)
    token = prefix.token_strings[-1]
    value = predict(recent, token, piece, first)
    return (doc, (recent + piece)[-100:], raw[consumed:]), value

