"""layers.1.mlp.down_proj:4445 - a sparse LaTeX/math-notation detector, plus two small positive cues.

What the component does, in plain terms:
  * Strongly NEGATIVE on the token that opens a delimiter or script inside LaTeX math:
    - the backslash of a delimiter right after a sizing word: \\left\\, \\right\\, \\big\\ (about -3.5);
    - a sign or operator written directly after a superscript/subscript mark: c^+, U^*, x_-,
      and merged tokens such as ^- or _- in xymatrix arrows (about -3).
    - a backslash command right after a subscript group, as in x_{i}\\ (about -1.5).
  * Mildly POSITIVE on two things:
    - a range tilde (~, ～, 〜) written right after a digit, as in 15~20 (about +0.8);
    - the first token of a new document when it opens a code file: import, #include,
      class, //, /* (about +1.2).
  * Zero everywhere else. Its variance is mostly in these few places; ordinary text gives
    tiny values that a zero prediction describes well.

Why: the component's large responses are on math-notation tokens, so a reader can
predict them from the current token and the token just before it.
"""

READS = ()

# Tokens that name a delimiter-sizing command (\left, \right, \big, ...), as they come out of the tokenizer.
SIZE_WORDS = {"left", "right", "big", "Big", "bigl", "bigr", "Bigl", "Bigr", "biggl", "biggr", "igl", "igr"}
# Tokens ending a subscript or superscript group, after which a backslash command starts.
SUB_END = ("}_", ")_", "]^", ")^", " ^", " _")
SIGNS = ("+", "-", "*")
TILDES = ("~", "～", "〜")
CODE_OPENERS = {"import", "#include", "//", "/*", "class"}


def after_script_mark(prev):
    """True when the previous token ends with a bare ^ or _ (a superscript or subscript mark)."""
    return prev[-1:] in ("^", "_") and prev[-2:] not in ("\\^", "\\_")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    core = cur.lstrip("^_")  # the token with any leading ^ or _ removed, e.g. "^-" -> "-"
    value = 0.0
    if cur == "\\" and prev in SIZE_WORDS:
        value = -3.5  # delimiter after \left, \right, \big
    elif cur == "\\" and prev in SUB_END:
        value = -1.5  # command right after a subscript group
    elif after_script_mark(prev) and cur.startswith(SIGNS):
        value = -3.0  # sign right after ^ or _
    elif cur[:1] in ("^", "_") and core.startswith(SIGNS):
        value = -3.0  # merged mark+sign tokens such as ^- and _-
    elif cur in TILDES and prev[-1:].isdigit():
        value = 0.8  # number-range tilde, 15~20
    elif prev == "<|endoftext|>" and cur in CODE_OPENERS:
        value = 1.2  # first token of a document that opens a code file
    return carry, float(value)

"""layers.1.mlp.down_proj:4446, a comma-after-discourse-marker detector.

What it does: this component is silent on most tokens, and fires on the punctuation that
closes a short phrase opening a sentence or clause. The strongest case is a comma right
after a transition or discourse marker ("Wait,", "However,", "Alternatively,", "Hmm,",
"Also,", "In addition,", "For example,"), which signals that a new thought, hedge or
aside is about to begin. The next word is often "maybe", "perhaps", "let", "but" or "if".
Other short openers ("Usually,", "Based on this,") fire more weakly, and the effect
fades with phrase length. Two smaller cases: a colon after a note-like label
("Note:", "Warning:", "TIP:") and "that" after "is" or "note" ("The point is that").

Everything else predicts 0. Activations are in units of the component's own output.
"""

READS = ()

# Transition / discourse-marker words, with how strongly a following comma responds.
MARKERS = {
    "wait": 2.7, "note": 2.7, "interestingly": 2.4, "actually": 2.2, "additionally": 2.2,
    "addition": 2.1, "also": 2.1, "besides": 2.0, "plus": 2.0, "importantly": 2.0,
    "moreover": 1.7, "however": 1.7, "alternatively": 1.7, "hmm": 1.7, "furthermore": 1.7,
    "now": 1.7, "particular": 1.7, "well": 1.6, "but": 1.6, "remember": 1.8,
    "more": 1.5, "way": 1.5, "so": 1.4, "therefore": 1.3, "thus": 1.3, "hence": 1.3,
    "no": 1.3, "yes": 1.2, "course": 1.2, "example": 1.1, "then": 1.0, "indeed": 1.0,
    "think": 1.0, "first": 0.9,
}
COMMA = {",", "，", "、"}
LABELS = {"note", "warning", "title", "tip", "edit", "update", "remember", "disclaimer"}
FALLBACK = 0.3       # other commas that close a short opening phrase
MAX_OPENER = 3       # opening phrases up to this many words
SENTENCE_END = (".", "!", "?", "\n", ":")


def opener_len(prefix):
    """Words since the last sentence break, before the current token."""
    n = 0
    for s in reversed(prefix.token_strings[:-1]):
        if any(c in s for c in SENTENCE_END):
            break
        if s.strip():
            n += 1
    return n


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if tok in COMMA:
        if prev in MARKERS:
            value = MARKERS[prev]
        elif 1 <= opener_len(prefix) <= MAX_OPENER:
            value = FALLBACK
    elif tok == ":" and prev in LABELS:
        value = 2.0
    elif tok == "that" and prev in {"is", "note"}:
        value = 1.3
    return carry, float(value)

