"""Approximate formatting-boundary responses, not general lexical variation.

A single space starting a line or a recognized quoted string is positive;
escaped newlines are stronger. Line endings and document age adjust strength.
Added lines in a diff receive a similar indentation response. Backslash runs
are positive normally, but negative after recent TeX commands; complete TeX
line-break commands are negative too. Smaller rules handle chat-user headers,
an initial end-of-text marker, and the strong document-initial 'Title:' colon.
Other tokens return zero. State resets at document boundaries.
"""
import re
import math

READS = ()
# These are TeX syntax, not a vocabulary of corpus-specific tokens.
TEX = re.compile(
    r'\\(?:begin|end|frac|sqrt|left|right|math|text|quad|hline|hfill|'
    r'alpha|beta|gamma|lambda|sigma|delta|xi|chi|mu|hat|dagger|rm|'
    r'partial|overline|nonumber|notag)'
)
OPEN_QUOTE = re.compile(r'''[(:=]\s*[frbuFRBU]*\\*["']$''')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, tail, previous, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' ':
        if tail.endswith('\\n'):
            value = 1.38 + 0.45 * math.exp(-position / 40)
        elif tail.endswith('\n'):
            value = 0.72 + 0.45 * math.exp(-position / 40)
            line = tail.rstrip('\r\n')
            if line.endswith('.'):
                value -= 0.3
            elif line.endswith((',', ';')):
                value -= 0.12
            elif line.endswith('>'):
                value += 0.3
            if '\t' in previous:
                value += 0.25
            if tail.endswith('\n\n'):
                value += 0.1
        elif tail.endswith('\n+'):
            value = 0.8
        elif OPEN_QUOTE.search(tail):
            value = 1.15
    if '\\\\' in token:
        value = (-0.95 if TEX.search(tail) else
                 max(0.3, 1.05 - 0.1 * (token.count('\\') - 2)))
    if tail.endswith('\\') and token in ('cr', 'newline'):
        value = -2.5 if token == 'cr' else -1.04
    if token == '\n' and previous == 'user' and position > 5:
        value = 0.24 if '</tool_call>' in tail else 0.17
    if position == 0 and token == '<|endoftext|>':
        value = 1.51
    if token == ':' and position == 1 and previous == 'Title':
        value = 10.09
    return (doc, (tail + token)[-200:], token, position + 1), value

"""Surface-rule approximation of a small, irregular early-MLP component.

It distinguishes attached calls from spaced parenthetical prose. Function-letter
arguments, plotting routines, uppercase function names and R-style assignments
shift calls negatively. Other code-formatting tokens get small corrections.
Document openings have a separate, coarse prior based on case and word meaning.
This does not reproduce the component's many token-specific fluctuations.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

@lru_cache(maxsize=8192)
def surface(s):
    t = s.strip()
    value = 0.002
    if '\t' in s and '\n' in s:
        value -= 0.09
    if t in ('\\n', '\\r'):
        value -= 0.055
    if t == '\\t':
        value -= 0.032
    if '_' in t:
        value += 0.023 + (0.029 if not t.strip('_') else 0)
    if re.search('[a-z][A-Z]', t):
        value += 0.022
    if re.match(r'^\.[A-Za-z]', t):
        value += 0.016
    if re.match(r'^@[A-Za-z]', t):
        value += 0.056
    if t.startswith('$'):
        value += 0.034
    if t == '::':
        value += 0.078
    if t and not t.strip('·'):
        value += 0.125
    return value


@lru_cache(maxsize=2048)
def opening_word(s):
    t = s.strip()
    if not (t.isascii() and t.isalpha()):
        return surface(s)
    classes = wordnet.categories(t.lower())
    value = -0.005
    value += 0.10 * s.startswith(' ')
    value += 0.05 * t.istitle() - 0.07 * t.isupper()
    for category, weight in (
        ('adj.all', 0.04), ('noun.food', 0.10), ('noun.shape', 0.02),
        ('noun.body', 0.02), ('noun.phenomenon', 0.04),
    ):
        if category in classes:
            value += weight
    return value


PLOTTING_ROUTINES = frozenset({
    'plot', 'hist', 'histogram', 'scatter', 'scatterplot', 'boxplot',
    'ggplot', 'ggpairs', 'barplot', 'lines', 'points', 'curve',
})


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, count, last_call = '', 0, -1000
    else:
        _, tail, count, last_call = carry
    value = surface(s)
    if s.startswith('('):
        match = re.search(r'[A-Za-z_][A-Za-z_0-9.]*$', tail)
        name = match[0] if match else ''
        value = 0.016
        if s.startswith('()'):
            value += 0.027
        if name.islower():
            value -= 0.018
            if count - last_call > 150:
                value -= 0.055
        if name.split('.')[-1] in PLOTTING_ROUTINES:
            value -= 0.20
        # These are the conventional letters for function-valued arguments.
        if s in ('(f', '(g', '(h'):
            value -= 0.146
        if '<-' in tail:
            value -= 0.124
        if '::' in tail:
            value += 0.026
        if re.search(r'\b[A-Z][A-Z_]{1,}$', tail):
            value -= 0.13
        last_call = count
    if count == 0:
        value = opening_word(s)
        if s == '\x00':
            value = 1.387
        elif s.lstrip().startswith(('{\\', '[\\')):
            value = 0.82
        elif s == ' $':
            value = 0.55
        elif s == '\\t':
            value = 0.726
        elif s.startswith('//\n'):
            value = 0.766
        elif s.startswith('/*\n'):
            value = -0.565
    if count == 1 and tail == 'Title' and s == ':':
        value = -0.667
    return (doc, (tail + s)[-300:], count + 1, last_call), value

