"""layers.1.mlp.down_proj:4448 -- a weak "code-identifier" detector.

This component's output is tiny and diffuse (RMS 0.04, and it almost never passes the
causal-importance threshold). Its sign follows the kind of token being read:

* positive on identifier-like tokens from code and technical text: snake_case
  (`_`, `__`), scope and shell/template punctuation (`::`, `$`, backtick), CamelCase
  words, and dotted names (`.is`, `.rs`);
* positive, a little, on Capitalised words;
* negative on escaped or whitespace text (`\\n`, `\\t`, real tabs and newlines);
* roughly zero on a bare opening parenthesis;
* a moderate positive value at the first token of each document, where the
  residual stream is least settled.

Everything else is about zero. The program reads only the newest token and whether a new
document has started, so it keeps no state beyond that.
"""

import re

READS = ()

CODE_IDENTIFIER = re.compile(r"_|::|[$`]|[a-z][A-Z]|^\.[a-z]")
ESCAPE_OR_WHITESPACE = re.compile(r"\\|\t|\n")
CAPITALISED_WORD = re.compile(r"^\s?[A-Z][a-z]+$")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.001
    if CODE_IDENTIFIER.search(token):
        value += 0.03
    elif ESCAPE_OR_WHITESPACE.search(token):
        value -= 0.007
    elif CAPITALISED_WORD.match(token):
        value += 0.009
    new_document = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_document:
        value += 0.023
    return None, float(value)

