"""A coarse initial-token response, not a word-by-word activation table.

The component is usually small once a document has a varied token history.
At its start, tabs tend positive and many code delimiters or decorative
punctuation runs tend negative. Alphabetic starts use weaker case/script
biases, with negative estimates for English articles and personal pronouns. The same estimate persists while the start token is repeated.
Token-specific, multi-token exceptions and small later fluctuations are omitted.
"""
import regex
from functools import lru_cache

READS = ()
ARTICLES = frozenset(('a', 'an', 'the'))
PERSONAL_PRONOUNS = frozenset(
    'i you he she it we they me him her us them'.split()
)


@lru_cache(maxsize=8192)
def initial_response(s):
    t = s.strip()
    if s.startswith('<|'):
        return 0.3 if s == '<|im_start|>' else 0.0
    if not t:
        if '\u00a0' in s:
            return -min(9.0, 2.5 * s.count('\u00a0'))
        if '\r' in s and '\n' not in s:
            return -5.0
        if '\t' in s and '\n' not in s:
            return 4.0 if s.strip('\t') == '' else 1.0
        return -0.25
    quoted = t[1:].lstrip('\\') if t.startswith('(') else ''
    if quoted.startswith(('\"', "'", '`')):
        return -10.5
    if t == '()':
        return -5.5
    if t == '::':
        return -10.0
    if set(t) == {'&'}:
        return -6.5
    if t == '!':
        return -4.0
    if t in ('=', '+', '-', '*', '/', '|', '$'):
        return -3.0 if s.startswith(' ') else -1.5
    if len(t) > 1 and len(set(t)) == 1 and not t[0].isalnum():
        c, n = t[0], len(t)
        if c == '#' and n <= 6:
            return 0.5
        if c in '=*' and n == 2 and not s.startswith(' '):
            return 3.0
        if c == '.' and n == 3:
            return 0.3
        if c in ':!^~+\\':
            return -min(11.0, 3.0 * n)
        return -3.8
    if len(t) > 1 and '\\' in t and not any(c.isalnum() for c in t):
        return -5.0
    if t in ':;' and '\n' in s:
        return -3.0
    if t.isdecimal():
        return -0.2
    if regex.search(r'\p{Script=Cyrillic}', t):
        return -0.7
    if regex.search(r'\p{Script=Han}', t):
        return 0.45
    if t.isalpha():
        if t.lower() in ARTICLES:
            return -1.0
        if t.lower() in PERSONAL_PRONOUNS:
            return -0.85
        if s.startswith(' '):
            return 0.0
        if t.istitle() and len(t) > 1:
            return 0.9
        return -0.5
    return -0.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True)
    else:
        carry = (doc, carry[1], carry[2] and token == carry[1])
    value = initial_response(prefix.token_strings[-1]) if carry[2] else 0.002
    return carry, float(value)

"""A fading indentation response at the first line breaks of a document.

Spaces and tabs at a line's beginning give a negative pulse, strongest early
in the document. It fades with the number of newline-bearing tokens. Width,
preceding braces/colons, and whether this continues a whitespace chunk adjust
that pulse. Line-leading comment markers get a smaller fading pulse.
Formatting tokens have small baseline offsets; other text stays near zero.
This describes the conspicuous formatting response, not smaller token-specific variations.
"""

READS = ()

# Very short whitespace chunks give smaller pulses than long indentation.
WIDTH_RELIEF = {1: 0.53, 2: 0.26, 3: 0.23, 4: 0.32, 8: 0.35}
COMMENT_MARKERS = {'#', '//', '/*', '*', '*/', '///', '<!--'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, 0, True, '')
    _, breaks, position, line_start, previous = carry
    text = prefix.token_strings[-1]
    blank = bool(text) and not text.strip(' \t\r\n')
    comment = text.strip() in COMMENT_MARKERS
    tab = '\t' in text
    newline = '\n' in text
    value = 0.0013

    if blank or comment or text.startswith('\t'):
        value = 0.0024 - 0.012 * tab - 0.0016 * newline + 0.009 * comment
        if position == 0:
            value -= 0.09
        decay = max(breaks, 1) ** -1.3
        width = len(text.split('\n', 1)[0].expandtabs(4))
        if blank and position > 0 and line_start and width > 0:
            if newline:
                value -= 0.20 * decay
            else:
                pulse = -0.86 + WIDTH_RELIEF.get(width, 0.0) - 0.13 * tab
                if previous.rstrip().endswith('{'):
                    pulse += 0.405
                if previous.rstrip().endswith(':'):
                    pulse += 0.23
                if not previous.endswith('\n'):
                    pulse += 0.19
                value += 0.021 + decay * pulse
        if comment and previous.endswith('\n'):
            value -= 0.114 * decay

    if text.strip(' \t\r\n'):
        line_start = False
    if newline:
        breaks += 1
        line_start = not text.rsplit('\n', 1)[1].strip(' \t\r')
    carry = (document, breaks, position + 1, line_start, text)
    return carry, float(value)

"""Recognize typographical rules and code/documentation boundaries.

A token dominated by repeated separator characters gets a negative value,
roughly quadratic in its run length, saturating at 64 characters. Continuing
such a run strengthens the response. Short hash/slash runs are instead
headings or comments. Other rules recognize familiar code and markup syntax;
ordinary words receive zero. This approximates the strong, structured
responses, not the component's numerous small word-specific responses.
"""
import re

READS = ()

# Magnitudes for a long horizontal rule, by its printed character.
RULE_STRENGTH = {
    '=': 6.2, '-': 7.2, '_': 9.3, '*': 7.9, '#': 6.0,
    '/': 5.5, '.': 3.9, '~': 5.0, '!': 1.0, '^': 2.2,
}
RUN = re.compile(r'([=\-_*#/.~!^═])\1+')
MODIFIERS = {'public', 'private', 'protected', 'static', 'abstract',
             'partial', 'export'}


def divider(token):
    text = token.strip()
    if not text or any(c.isalnum() for c in text):
        return None
    runs = list(RUN.finditer(text))
    if not runs:
        return None
    run = max(runs, key=lambda m: len(m[0]))
    char, length = run[1], len(run[0])
    minimum = 2 if char == '═' else 3
    if length < minimum or length < 0.65 * len(text):
        return None
    return char, length


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    value = 0.0
    rule = divider(token)
    if rule:
        char, n = rule
        value = -RULE_STRENGTH.get(char, 0.0) * (min(n, 64) / 64)**2
        if char in '#/' and n < 7 and '\n' not in token:
            value = 0.0
        if char == '═':
            value = -0.24 * n
        if n >= 24 and '\n' in token and char in '*#':
            value *= 0.6
        before = divider(previous)
        if before and before[0] == char:
            value -= 1.4 * min(before[1], 96) / 64 * min(n, 32) / 16
        if char == '=' and n == 3:
            value = -0.21 if token.startswith(' ') else -0.34
        elif n < 24 and '\n' in token:
            value -= 0.15

    if text == '@Override':
        value = -4.2
    elif text == 'Override' and previous.rstrip().endswith('@'):
        value = -3.6
    elif text == 'override' and previous.strip() in MODIFIERS:
        value = -2.4
    elif text == '/**':
        value = -0.85
    elif text == '*/':
        value = -0.6
    elif previous.rstrip().endswith('\\'):
        if text == 'end':
            value = -0.7
        elif text in ('ref', 'eqref'):
            value = -1.25
        elif text in ('label', 'section', 'subsection', 'subsubsection'):
            value = -1.9
        elif text in ('include', 'new'):
            value = -2.7
    elif text == 'summary' and previous.strip() in ('<', '</'):
        value = -1.6
    elif text in ('#include', '#endif') or (
        text in ('include', 'endif') and previous.rstrip().endswith('#')
    ):
        value = -0.65
    elif text == '};' and '\n' in token:
        value = -0.52
    elif text == 'class' and previous.strip() in MODIFIERS:
        value = 1.1
    return None, value

"""A local grammatical-complement detector, chiefly necessity and obligation.

English 'to' is negative after need/have, especially with a personal subject;
negation and questions weaken this response. Chinese 得 is positive after
verbs (a result/degree complement), but negative after modal adverbs or
pronouns ('must'). Dictionary compounds are treated separately. 该/該,
prohibitive 别/別, and ordering instructions with 先 have negative responses.
The idiom 'it depends' is treated as a negative contingency marker.
These are approximate local rules, not a full grammatical analysis.
"""
from collections.abc import Mapping
from functools import lru_cache
import cedict

READS = ()
PURPOSE_NOUNS = {
    'task', 'goal', 'aim', 'objective', 'job', 'key', 'step',
    'solution', 'plan', 'purpose', 'idea', 'challenge',
}
PRONOUNS = {
    '我', '你', '您', '他', '她', '它', '我们', '我們',
    '你们', '你們', '他们', '他們', '自己',
}
MODAL_ENDINGS = set('还還就也都才可真只又先必应應能要会會得非')

@lru_cache(maxsize=4096)
def is_verb(text):
    return any(g.startswith('to ') for g in cedict.glosses(text))

@lru_cache(maxsize=4096)
def is_compound(text):
    return bool(cedict.glosses(text))


def step(carry, prefix, upstream: Mapping):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else []
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    history = [''] * (3 - len(recent)) + [s.strip().lower() for s in recent]
    b, before, prev = history
    value = 0.001
    if word == 'to':
        value = 0.01 if recent else 0.5
        if prev in {'need', 'have', 'needs', 'needed', 'has', 'had'}:
            value = -0.9
            value += 0.7 * (prev in {'needs', 'needed', 'has', 'had'})
            value -= 0.4 * (before in {'i', 'we'})
            value -= 0.15 * (before == 'you')
            value += 0.6 * (before in {"'t", '’t', 'not', 'never'} or b == 'not')
            value -= 0.5 * (before in {"'ll", '’ll', "'d", '’d'})
            value -= 0.22 * any(ch in b for ch in ',.!?\n')
            value += 0.3 * (b in {'that', 'which', 'what', 'if', 'when', 'whether'})
            value += 0.4 * (b in {'do', 'does', 'did'} or before in {'do', 'does', 'did'})
        elif prev == 'got':
            value = -1.3 if before in {"'ve", '’ve', 'have', 'has'} else -0.2
        elif prev in {'important', 'necessary', 'essential'}:
            value = -0.33
        elif prev in {'want', 'wants', 'wanted', 'order', 'able'}:
            value = -0.10
        elif prev == 'is' and before in PURPOSE_NOUNS:
            value = -0.6
    elif word == '得':
        if prev and is_compound(prev[-1:] + word):
            value = 0.5
        elif prev and (prev[-1:] in MODAL_ENDINGS or prev in PRONOUNS):
            value = -4.5
        else:
            value = 2.3 if is_verb(prev) else -0.2
    elif (word.endswith('得') and len(word) == 2
          and word[0] in MODAL_ENDINGS):
        value = -3.4
    elif word in {'得多', '得好', '得太'}:
        value = 2.3
    elif word == '得很':
        value = 0.65
    elif word in {'得到', '得出', '得起'}:
        value = 1.4 if is_verb(prev) else 0.4
    elif word == '得了':
        value = 3.5 if is_verb(prev) else 0.3
    elif word == '得以':
        value = -0.5
    elif word in {'该', '該'}:
        modal = (prev in PRONOUNS or prev.endswith(('也', '就', '才', '更'))
                 or '知' in prev or prev in {'是不是', '还是', '還是', '究竟'})
        value = -3.9 if modal else -0.85
    elif word in {'该如何', '該如何', '该怎么', '該怎麼'}:
        value = -2.0
    elif word in {'别', '別'}:
        if prev and is_compound(prev[-1:] + word):
            value = -0.28
        elif prev and (prev[-1:] in MODAL_ENDINGS or prev in PRONOUNS):
            value = -4.0 if word == '别' else -2.9
        else:
            value = -1.6 if word == '别' else -0.6
    elif word == '先':
        value = -0.27
        if prev.endswith(('要', '得', '必须', '必須', '必')):
            value = -2.2
        elif prev.endswith(('你', '您', '请', '請', '可以')):
            value = -1.35
    elif word == '需要注意':
        value = -0.9
    elif word == 'depends':
        contingent = (prev == 'it' or
                      (prev in {'all', 'really'} and before in {'it', 'this'}))
        value = -1.7 if contingent else 0.3
    return (doc, (recent + [text])[-3:]), float(value)

programs.haiku:
"""Obligation markers: the word that names the required action after 'need to' / 'have to'
(and Chinese obligation words 该 別 先) is pushed negative; a document's first token,
which the model sees with no context, gets a small positive value."""
READS = ()

NEED = {"need", "needs", "needed", "have", "has", "had", "necessary", "essential", "important"}
CN_OBLIGATION = {"该", "該", "别", "別", "先"}

def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.15
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip()
    if cur == " to" and prev in NEED:
        return None, -0.9 if prev.startswith("need") else -0.6
    if cur.strip() in CN_OBLIGATION:
        return None, -0.8
    return None, 0.0

programs.sol:
"""A spelling detector for r-m clusters exposed by tokenization.

Short fragments such as 'arm' and an m beginning immediately after r get
large responses. Longer, familiar words containing the same letters are
usually much weaker. Length and dictionary frequency approximate these
lexical differences; no token identities are memorized. A small response
also follows a detected cluster into the next fragment of its word,
and there is a weaker response at an l|m boundary.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex

READS = ()
ALPHABETS = regex.compile(r'[\p{Latin}\p{Greek}\p{Cyrillic}]+')


@lru_cache(maxsize=32768)
def spelling(text):
    return ALPHABETS.sub(lambda m: anyascii(m.group()), text).lower()


@lru_cache(maxsize=16384)
def familiarity(word):
    return max(zipf_frequency(word.strip(), language)
               for language in ('en', 'de', 'fr', 'es', 'it', 'pt'))


def response(s, previous):
    word = s.strip()
    n = len(word)
    boundary = s.startswith('m') and previous.endswith('r')
    if boundary:
        if n <= 2:
            return 4.8
        if n == 3:
            return 2.0 if familiarity(word) <= 5.0 else 4.8
        if n == 4:
            return 1.7
        return 0.8 if n == 5 else 0.1

    if word == 'rm':
        return 4.5
    if 'rm' in s:
        f = familiarity(word)
        if n <= 3:
            if s[:1].isspace():
                return 2.3
            return 3.2 if f <= 4.25 else 4.4
        if 'arm' in s:
            if n >= 7:
                return 0.43
            return 1.8 if f <= 4.8 else 0.46
        if word.find('rm') <= 1:
            return 2.4
        if n == 4:
            if f > 5.0:
                return 0.15
            return 0.4 if 'orm' in s else 1.95
        if n < 7 and 1.3 < f < 3.4:
            return 1.4
        return 0.06

    if 'rm' in previous and s[:1].isalpha():
        return 0.3
    if s.startswith('m'):
        return 0.2 if previous.endswith('l') else -0.07
    return 0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    current = spelling(prefix.token_strings[-1])
    return (doc, current), float(response(current, previous))

"""A spelling-family detector, strongest when a token completes a split root.

Positive families include cede/ceed (precede, proceed, exceed), cide
(decide), cess, and related cend/cis fragments. Whole words have weaker,
family-specific responses. Accents are ignored. The phrases 'excess of'
and 'proceeds of' have a strong response on 'of'. Other continuations of
c before e/i/u get a small negative response; unrelated text gets zero.
This approximates the large spelling-related activations, not background
variation on arbitrary words. Immediate negators reduce the exceed response;
perfect-tense auxiliaries reduce the response to decided.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()

# Related whole-word forms do not respond as strongly as split roots.
CESS_WORDS = {
    'excess': 1.2, 'excessive': 0.4,
    'concession': 3.4, 'concessions': 1.1,
    'recession': 1.1, 'successor': 1.3, 'successors': 0.3,
    'cess': 1.5, 'cease': 1.3,
}


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


@lru_cache(maxsize=100000)
def activation(token, previous):
    s, p = plain(token), plain(previous)
    word = s.strip()
    if s == ' of' and p.strip() in ('excess', 'proceeds'):
        return 6.0 if p.strip() == 'excess' else 5.4
    if re.fullmatch(r'\s*(?:exceed|proceed|preced|decid|coincid)\w*', s):
        if 'exceed' in s:
            negated = p.strip() in ('not', 'never', 'cannot', "n't")
            return 2.5 if negated else 3.9
        if 'proceedings' in s:
            return 0.7
        if 'proceed' in s:
            return 3.1
        if 'preced' in s:
            return 3.2
        if 'coincidence' in s:
            return 0.5
        if word == 'decided' and p.strip() in ('have', 'has', 'had'):
            return 1.1
        return 2.2
    if word.startswith('predecessor'):
        return 0.8
    if word.startswith('succeed'):
        return 1.5
    if word in CESS_WORDS:
        return CESS_WORDS[word]
    if re.fullmatch(r'\s*(?:pro|con|re|ex|suc|ante|ac|se)?ced', s):
        return 3.1
    if not s or s[0].isspace() or not s.isalpha():
        return 0.0

    # Capitalized identifier segments are not prose-word continuations.
    if (token[0].isupper() and previous[-1:].islower()
            and (not token.isupper() or token in ('ID', 'Id'))):
        return 0.0
    if s.startswith('edur'):  # procedure, not the cede/ceed spelling
        return 0.0

    joined = p + s
    roots = r'c(?:eed|ed|id|ess|is|end)|(?:super|pre)s[ei]d'
    for match in re.finditer(roots, joined):
        if not match.start() < len(p) < match.end():
            continue
        root = match[0]
        if re.search(r'c(?:ee|e)d', root):
            # A plain -ed ending after c need not be the cede root.
            if s == 'ed' and not re.search(
                    r'(?:^|\W)(?:pre|pro|de|re|ex|ac|suc)?c$', p):
                return 1.1
            return 6.8
        if 'cid' in root:
            if s.startswith(('idad', 'idual')):
                return 0.0
            if s.startswith('ido'):
                return 0.9
            if s.startswith(('idental', 'idents')):
                return 1.3
            if s.startswith('id'):
                return 3.5
        if 'cess' in root:
            return 4.2
        if root.endswith('end'):
            return 2.0
        if root.startswith(('pres', 'supers')):
            return 3.4
        return 3.0 if re.search(r'ciss|cisor', joined) else 0.7

    # Roots contained in one fragment, and their continued suffixes.
    if re.match(r'^(?:ceed|ced|cide|icid|cess)', s):
        if re.search(r'(?:produ|indu|for|coer|pla|repla|redu)$', p):
            return 0.0
        if s.startswith('ceed'):
            return 4.4
        if s.startswith('ced'):
            return 3.1
        return 2.5 if 'cid' in s else 1.8
    if re.search(r'(?:ced|ceed|cid|cess|cend)$', p):
        if not re.search(
                r'(?:access|success|process|necess|princess|acid|elucid)$', p):
            return 2.1
    return -0.2 if p.endswith('c') and s[0] in 'eiu' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, older = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    # Some accented cede spellings split c | é | d across three tokens.
    context = previous
    if previous in ('é', 'è', 'ê', 'éd'):
        context = older + previous
    return (doc, token, previous), activation(token, context)

programs.haiku:
"""Latin "cede / cess / cid" word-root detector (layers.1.mlp.down_proj, component 4454).

What it does: this component reads the word being spelled out, one token at a time, and
switches on when that word carries the Latin verb root from "cedere" (to go, yield) or
"caedere" (to cut), as in English and Romance verbs and nouns:
  - strongest on "ceed" / "cede": proceed, exceed, succeed, precede, accede, concede, cede,
    and Spanish/French/Italian forms (proceder, acceder, procedimiento, précédent);
  - medium on "cess": excess, concession, cession, recession, recessed;
  - medium on "ceas": ceased, cease;
  - medium on "cid": decide, decided, suicide, herbicide, fungicide;
  - on "ced" only after a prefix such as pro-, pre-, ex-, suc-, con-, de-, ac-
    (proced-, preced-, exced-), not on English "-ced" past tenses (advanced, placed);
  - weaker on the word "of" right after such a word ("in excess of", "proceeds of").
It is 0 everywhere else, which is nearly all text: the component is almost silent.

Limits: it ignores the many negative values (about -1 to -6 on odd tokens such as
"videocitta", "ccw", "czech"), and it cannot see the magnitude difference between a
rare Romance form (proced-, exced-, often 5 to 9) and a common English one (decided, ~2).
Measured on the eval rows it explains about a fifth of the variance (0.21, r 0.46) and
recovers about 22% of the component's KL effect on the model (kl_fraction 0.78).
"""

import re
import unicodedata

READS = ()

# Common English words that contain the letters by accident, not the Latin root.
NOT_ROOT = re.compile(
    r"process|access|success|princess|necess|acid|cider|cedar|cidad|procedur|incident|accident"
)
PREFIXED_CED = re.compile(r"(pro|pre|ex|suc|con|ac|de|re|se|inter|sup|dec)ced")
ROOT_WORD = re.compile(r"ceed|cede|cess|ced|cid")


def _plain(text):
    """Lowercase, accents removed, so "procédé" reads as "procede"."""
    return "".join(
        ch for ch in unicodedata.normalize("NFD", text.lower()) if unicodedata.category(ch) != "Mn"
    )


def _strength(word):
    """How strongly a (partial) word shows the root, from its letters so far."""
    if NOT_ROOT.search(word):
        return 0.0
    if re.search(r"ceed|cede", word):
        return 3.0
    if PREFIXED_CED.search(word):
        return 3.0
    if "cess" in word:
        return 2.0
    if "cid" in word:
        return 1.6
    if "ceas" in word:
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    # Text of the current document up to this token (a new document starts a fresh word).
    docs = prefix.document_ids
    start = len(docs) - 1
    while start > 0 and docs[start - 1] == docs[-1]:
        start -= 1
    text = _plain(prefix.text_prefixes[-1])
    if start > 0:
        text = _plain("".join(prefix.token_strings[start:]))
    # The word being spelled: letters from the last word break up to this token.
    word = re.search(r"[^\W\d_]*$", text).group()
    before = re.findall(r"[^\W\d_]+", text[: len(text) - len(word)])
    previous = before[-1] if before else ""
    value = _strength(word)
    if value == 0.0 and word == "of" and ROOT_WORD.search(previous):
        value = 1.5  # "in excess of", "proceeds of"
    return None, value

programs.sol:
"""Approximate negative responses at source-code type boundaries.

Track generic angle brackets and nearby ASCII identifiers. Predict stronger
negative values at generic commas and constraints; weaker ones at type-list
brackets, inheritance, constant assignment, and the end of a type import.
Error/Result/Exception names are recognized in scoped or generic contexts.
Everything else is zero: smaller lexical fluctuations are not modeled.
"""
import re

READS = ()
NAME = re.compile(r'[A-Za-z_$][A-Za-z_0-9$]*$')
OUTCOMES = {'Error', 'Exception', 'Result'}
MAPS = {'Map', 'HashMap', 'TreeMap', 'IMap', 'Dictionary', 'BTreeMap'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail, depth = ('', 0) if start else carry[1:]
    token = prefix.token_strings[-1]
    s = token.strip()
    match = NAME.search(tail.rstrip())
    name = match.group() if match else ''
    upper = bool(name and name[0].isupper())
    generic = depth > 0
    angle = re.search(r'([A-Za-z_][A-Za-z_0-9]*)<[^<>]*$', tail)
    value = 0.0

    if s == 'extends':
        value = -5.93 if generic and upper else -0.81
    elif s == ':' and upper and len(name) == 1:
        if generic or re.search(r'\bwhere\b[^;{}]*$', tail):
            value = -3.28
    elif s == '=' and generic and upper:
        value = -6.14
    elif s.startswith(',') and generic:
        value = -5.26 if angle and angle[1] in MAPS else -2.04
    elif s in ('|', '&') and generic:
        value = -2.32
    elif s.startswith('<') and not s.startswith('</') and name:
        if generic:
            value = -1.18
        elif upper and not name.isupper():
            value = -1.0
    elif (s.startswith('>') or s.startswith('[]>')) and generic:
        value = -0.69
    elif s.startswith(';') and upper:
        if re.search(r'\b(?:import|using)\s+[^;\n]*$', tail):
            value = -1.25
    elif s == '=' and upper:
        if re.search(r'\b(?:const|final|static)\b[^;{}]*$', tail):
            value = -1.02
    elif s in OUTCOMES:
        if tail.endswith('::'):
            value = -2.39
        elif generic:
            value = -3.04

    # Functions as well as classes can introduce generic parameter lists.
    before = tail
    for char in token:
        if char == '<' and (depth or NAME.search(before)):
            depth += 1
        elif char == '>':
            depth = max(0, depth - 1)
        elif char in ';{}':
            depth = 0
        before = (before + char)[-160:]
    return (doc, (tail + token)[-240:], depth), 0.0 if start else value

programs.haiku:
"""Type-level syntax in code: generic type arguments and declarations (a negative response).

Component p-82af68dd@100000/layers.1.mlp.down_proj:4455 (layer 1, MLP down projection)
is nearly silent, and when it fires it is negative. Its large negative values sit in
the type-level parts of code:

- inside a generic's angle brackets, as in `Map<UUID, ItemStack>`,
  `Result<String, Vec<String>>`, `Iterator<Item = T>`, `impl<T: Send>`,
  `Record<string, any>`: the separator right after the first type name (the comma in
  `Map<UUID,`, the `=` in `Iterator<Item =`) is strongly negative; later separators,
  type names and the closing `>` are mildly negative;
- the opening `<` right after a type name is mildly negative;
- `extends` after a type name (`class X extends Y`) is negative;
- `=` in a type alias (`type Output = ...`) is strongly negative;
- `for` in a Rust impl (`impl Drop for ...`) is negative.

Everything else is predicted as 0.

A `<` opens a generic when it follows a capitalised type name, or a primitive type word
such as `int` or `string`, so `Map<` and `Result<` count while `x < 2` in maths or prose
does not. Special tokens (`<|endoftext|>`), HTML closers (`</`) and comparisons are
skipped. The program keeps a stack of open brackets, reset at each document start.
"""

import re

READS = ()

# a type name: a capitalised identifier, or a primitive type word
TYPE_NAME = re.compile(
    r"(?:[A-Z][A-Za-z0-9_]*|int|long|byte|char|bool|boolean|void|float|double|str|string"
    r"|number|any|unknown|object)$"
)
SEPARATOR_WORDS = {":", "=", "|", "&", "extends", "for", "implements"}

FIRST_ARG = -5.5  # separator right after the first type name inside <...>
OTHER_SEP = -1.0  # other separators inside <...>
NAME_IN = -1.0  # a type name inside <...>
OPENER = -1.0  # a generic '<' opened right after a type name
CLOSER = -1.0  # a '>' inside <...>
EXTENDS = -3.5  # `X extends`
TYPE_ALIAS = -5.5  # `type X =`
IMPL_FOR = -4.0  # `impl X for`


def _after_type(prev):
    return bool(TYPE_NAME.search(prev))


def _is_separator(tok):
    return "," in tok or tok.strip() in SEPARATOR_WORDS


def step(carry, prefix, upstream):
    # carry: (open brackets as [is_generic, commas_seen], previous token,
    #         the token before it, document id)
    stack, prev, prev2, doc = carry if carry is not None else ([], "", "", None)
    stack = [list(b) for b in stack]
    tok = prefix.token_strings[-1]
    if prefix.document_ids[-1] != doc:
        stack, prev, prev2, doc = [], "", "", prefix.document_ids[-1]
    after_name = _after_type(prev)
    word = tok.strip()

    value = 0.0
    if stack and stack[-1][0]:  # the innermost open bracket is a generic
        if ">" in tok:
            value = CLOSER
        elif _is_separator(tok):
            value = FIRST_ARG if (stack[-1][1] == 0 and after_name) else OTHER_SEP
        elif TYPE_NAME.search(tok):
            value = NAME_IN
    elif tok.startswith("<") and not tok.startswith(("<|", "</")) and after_name:
        value = OPENER
    if word == "extends" and after_name:
        value = EXTENDS
    if word == "=" and after_name and prev2.strip() in ("type", "typedef"):
        value = TYPE_ALIAS
    if word == "for" and after_name and prev2.strip() == "impl":
        value = IMPL_FOR

    # update the bracket stack with this token
    if "<" in tok and not tok.startswith(("<|", "</", "<=", "<<")):
        head = tok[: tok.index("<")]
        stack.append([bool(TYPE_NAME.search(head)) or (not head and after_name), 0])
    if ">" in tok and "->" not in tok and "=>" not in tok:
        for _ in range(tok.count(">")):
            if stack:
                stack.pop()
    if "," in tok and stack:
        stack[-1][1] += 1
    stack = stack[-10:]
    return (stack, tok, prev, doc), float(value)

