"""A local spelling approximation, strongest for many and short ny/ni pieces.

'many' is weak after degree expressions such as 'how many', but strongly
negative otherwise. Short ny/ni fragments also give negative values, most
strongly when y continues an n-ending token. Longer whole words are not
searched for these pairs. Repeated middle dots have a positive response.
The rules only use the current and previous tokens, reset at each document;
they do not capture all context-dependent differences in amplitude.
"""
READS = ()


def predict(token, previous):
    s, p = token.lower(), previous.lower()
    word = s.lstrip()
    continuation = bool(p) and p[-1].isalpha() and not s[:1].isspace()
    if token == '··' and '·' in previous:
        return 2.11
    if word == 'many' and not continuation:
        if p.strip() in ('how', 'so', 'too', 'as', 'very', 'infinitely'):
            return -0.18
        return -3.31 if p.strip() in ('in', 'for') else -2.37
    if word == 'any' and not continuation:
        return -0.29
    if continuation and p.endswith('n') and not p.endswith('\\n'):
        if s == 'y':
            return -6.20 if p.endswith(('en', 'gn')) else -3.20
        if s.startswith('yl'):
            return -4.05
        if s.startswith('y'):
            return -2.24
        if s in ('i', 'ie', 'ies', 'ier', 'iers', 'ied', 'iy', 'ij'):
            return -1.65 if s == 'i' else -1.34
        if s.startswith('ey'):
            return -2.56
    if word.isalpha() and word.endswith('ny') and len(word) <= 5:
        if len(word) <= 3:
            if continuation:
                short = len(previous.strip()) <= 3
                capitalized = any(c.isupper() for c in previous)
                return -3.22 if short or capitalized else -1.95
            return -2.25
        return -0.54 if word.endswith('nny') else -1.13
    if word.isalpha() and len(word) <= 4 and word.endswith('ni'):
        return -0.91 if continuation else -0.19
    if continuation and p.endswith('н') and s in ('и', 'ы', 'ь', 'і'):
        return -0.81
    if word.isalpha() and len(word) <= 4 and word.endswith(('ни', 'ны', 'нь')):
        return -0.29
    if token == 'ニ':  # Katakana ni
        return -1.15
    if token == '尼':  # Han character read ni in Mandarin
        return -1.86
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), predict(token, previous)

