    elif token == '机' and old.endswith('手'):
        value = -9.0
    if token == 'フォ':
        value = -4.0 if old.endswith('スマート') else -0.7
    elif token == 'ホ':
        value = -7.0 if old.endswith('クロ') else -1.3
