             'to lie', 'to sit', 'to crouch', 'to imprison', 'to confine',
             'to apply', 'to load', 'to deploy', 'to add', 'to penetrate',
             'to infuse', 'to write', 'to inject', 'to install',
             'to lock', 'to squeeze', 'to carry', 'to bring', 'to map',
             'to run', 'to walk', 'to fall', 'to use', 'to distribute')
