    elif t in {'纳入', '融入'}:
        value = -1.8
    elif t in {'投入', '投身', '包含', '包含了'}:
        value = -0.95
    elif t in {'出现在', '存在于', '投入到'}:
        value = -4.3 if t == '投入到' else -1.8
    elif t == '卧':  # lying down
        value = -2.1
