    elif t in {'在', '于', '入', '进', '到', '到了', '其中', '了'}:
        if prev.endswith('参与'):
            value = -3.3
        elif t in {'到', '到了'} and prev.endswith('入'):
            value = -5.0
        elif t in {'到', '到了'} and prev.endswith(('应用', '添加')):
            value = -3.8
        elif t == '其中':
