VERBS = {'come', 'bring', 'look', 'think', 'know', 'hear', 'learn', 'read',
         'tell', 'remind', 'inform', 'notify', 'pull', 'call', 'ask', 'speak'}
PRONOUNS = {'me', 'you', 'him', 'her', 'us', 'them', 'it'}


@lru_cache(maxsize=8192)
def verb(word):
    return next((v for v in wordnet.base_forms(word) if v in VERBS), word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, before, previous = ('', '', '')
    last_raw = ''
