    } else previous

    if word == 'up':
        if root == 'come':
            value = -9.2 if previous == 'come' else -8.2
        elif root in {'bring', 'look'}:
            value = -3.3
        elif root == 'think':
            value = -5.0
        elif root in {'pull', 'call'}:
            value = -1.5
        elif previous in PRONOUNS and verb(before) in {'bring', 'look'}:
            value = -3.7
    elif word == 'with':
        if previous == 'up' and verb(before) == 'come':
            value = -5.3
        elif root == 'come':
            value = -1.5
        elif previous == 'familiar':
            value = -0.65
    elif word == 'of':
        if root == 'know':
            value = -8.0
        elif root == 'think':
            value = -5.7 if previous == 'thinking' else -4.1
            if previous == 'thought' or before in {'me', "'s", '’s'}:
                value = -2.6
        elif root == 'hear' or previous == 'learned':
            value = -4.0 if previous != 'hear' else -2.7
        elif previous in {'aware', 'proud'} or root == 'tell':
            value = -2.5
        elif previous in PRONOUNS:
            source = verb(before)
            if source not in VERBS:
                source = verb(old + before)  # e.g. Rem + inds + me + of
            if source == 'remind':
                value = -4.8
            elif source in {'inform', 'notify'}:
                value = -3.3
    elif word == 'about':
        value = -0.12
        if root in {'know', 'learn', 'read'}:
            value = -2.5
        elif root == 'hear':
            value = -5.3 if previous == 'heard' else -2.5
        elif root == 'think':
            value = -1.2 if previous == 'think' else -1.8
        elif previous == 'more':
            value = -0.45
        elif previous in PRONOUNS and verb(before) == 'tell':
            value = -2.5
        elif root in {'ask', 'speak'}:
            value = -0.85
    elif word in {'across', 'along'} and root == 'come':
        value = -4.0
    elif word == 'mind' and previous == 'to':
        value = -8.5 if verb(before) == 'come' else -4.0
    elif word == 'more' and root in {'learn', 'know'}:
        value = -1.5
    elif word == 'think':
        if previous == 'me':
            value = -1.15
        elif previous in {'can', 'could'}:
            value = -1.3
        elif previous == 'to' and before in {'try', 'trying'}:
            value = -1.4
    elif word in {'recall', 'remember'}:
        if previous in {'cannot', "'t", '’t', 'not'}:
            value = -3.0 if word == 'recall' else -1.6

