        value = 0.8
    if word and set(word) == {'·'} and last_raw.endswith('·'):
        value = 2.53

    history = (before, previous, word) if word else (old, before, previous)
    return (doc, history, raw), value

"""A surface-language detector for mathematical extrema and optimization.

Transliterates text and recognizes min/max roots, their endings, and named
optimization phrases. Extremal qualifiers strengthen 'possible'; quantifiers
and formula-like context strengthen 'such'. Chinese min/max terms are also
recognized. Constants approximate typical observed activations. History resets
at document boundaries; unmatched positions return zero.
"""
import re
from anyascii import anyascii

READS = ()
EXTREMA = {
    'min', 'max', 'minimum', 'maximum', 'minimal', 'maximal',
    'minima', 'maxima', 'extrema', 'extremum', 'infimum', 'supremum',
}
SUPERLATIVES = {
    'smallest', 'largest', 'highest', 'lowest', 'shortest', 'longest',
    'greatest', 'least', 'best', 'worst', 'earliest', 'latest', 'fewest',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    text = anyascii(raw) if not raw.isascii() else raw
    s = re.sub(r'^[\W_]+|[\W_]+$', '', text.lower())
    joined = history + text
    words = re.findall(r'[a-z]+', history.lower())
    adjacent = re.search(r'([a-z]+)[\s_-]*$', history.lower())
    prev = adjacent.group(1) if adjacent else ''
    match = re.search(r'[a-z]+$', joined.lower())
    word = match.group() if match else ''
    # A continuation may finish a word begun in an earlier token.
    continuation = bool(text and text[0].isalpha())
    full = word if continuation else s
    value = 0.0
    if s in {'argmax', 'argmin', 'minmax', 'minimax'}:
        value = 5.0
    elif s in {'min', 'max'} and (full == s or prev == 'arg'):
        if re.search(r'\\\s*$', history):
            value = 6.3
        elif prev == 'arg' or history.lower().endswith('arg\\'):
            value = 8.09
        elif re.search(r'=\s*$', history):
            value = 2.02
        else:
            value = 0.68
    elif s in {'inf', 'sup', 'lim'} and full == s:
        value = 0.22
        if re.search(r'\\\s*$', history):
            value = 1.57 if s == 'lim' else 6.14
        elif prev == 'lim':
            value = 6.0
    elif full.endswith(('extremum', 'supremum', 'infimum')):
        value = 12.74
    elif full.endswith(('extrema', 'minima', 'maxima')):
        value = 5.32
    elif full.endswith('extremal'):
        value = 9.0
    elif s in {'extrem', 'suprem', 'infim'} or full.endswith('extrem'):
        value = 1.44
    elif s in {'maxim', 'minim'} or full.endswith(('maxim', 'minim')):
        value = 1.76
    elif full.endswith(('minimum', 'maximum', 'maksimum')):
        value = 1.87 if full.endswith('minimum') else 1.36
        if continuation and s in {'um', 'imum'}:
            value = 3.87
        if prev in {'local', 'global', 'relative', 'absolute', 'find', 'finding'}:
            value = 4.01
    elif full.endswith(('minimal', 'maximal')):
        value = 1.9 if full.endswith('minimal') else 1.73
        if prev == 'the':
            value = 3.12 if full.endswith('minimal') else 2.8
    elif re.search(r'(maxim|maksim|maksym|minim|extrem)i[sz](e|es|ed|ing|ation|er|ers)?$', full):
        value = 2.78
        if continuation and s not in {'minimize', 'maximize', 'minimizing', 'minimized'}:
            value = 3.9
    elif full.endswith(('minimo', 'maximo', 'minimos', 'maximos')):
        value = 2.77
    elif s in {'optimal', 'optim', 'optimize', 'optimise', 'optimizer', 'optimized'}:
        value = 0.5
    elif s in {'optimization', 'optimisation', 'optimizing', 'optimising'}:
        value = 1.36
        if prev in {'linear', 'nonlinear', 'constrained', 'convex', 'mathematical', 'polynomial'}:
            value = 3.81
    elif s == 'shortest':
        value = 1.3
    elif s in SUPERLATIVES:
        value = 0.11
    if raw.strip() in {'最小', '最大', '最小化', '最大化'}:
        value = 1.7
    elif raw == '值' and history and prefix.token_strings[-2] in {'最小', '最大'}:
        value = 6.5
    # Familiar mathematical multiword expressions.
    if s in {'programming', 'program'}:
        if prev in {'linear', 'nonlinear'}:
            value = 11.89
        elif prev in {'integer', 'quadratic', 'fractional', 'convex', 'nonconvex', 'matrix'}:
            value = 6.38
        elif prev == 'dynamic':
            value = 3.8
    elif s in {'point', 'points'}:
        if prev in {'critical', 'stationary', 'extreme'}:
            value = 5.61
        elif prev in {'saddle', 'limit', 'feasible', 'interior'}:
            value = 2.65
        elif prev == 'fixed':
            value = 1.09
    elif s in {'path', 'paths'} and prev in {'shortest', 'longest'}:
        value = 5.71 if prev == 'shortest' else 1.5
    elif s == 'spanning' and prev in {'minimum', 'minimal'}:
        value = 5.09
    elif s in {'flow', 'cut'} and prev in EXTREMA:
        value = 4.35
    elif s in {'value', 'values'}:
        if prev in {'minimum', 'minimal'}:
            value = 5.34
        elif prev in {'maximum', 'maximal', 'max', 'min'}:
            value = 1.86
        elif prev == 'possible' and any(w in EXTREMA | SUPERLATIVES for w in words[-3:-1]):
            value = 1.98
        elif prev == 'absolute':
            value = 0.47
    elif s in {'of', 'over', 'between'}:
        if prev in {'maximum', 'maximal'}:
            value = 4.6
        elif prev in {'extrema', 'extremum', 'infimum', 'supremum'}:
