            prev in {'value', 'values', 'number', 'points', 'point'}
            and any(w in EXTREMA | SUPERLATIVES for w in words[-4:-1])
        ):
            value = 2.72
    elif s == 'possible':
        value = -0.05
        if prev in {'minimal', 'maximal', 'smallest', 'largest', 'greatest', 'lowest', 'least'}:
            value = 3.69
        elif prev in EXTREMA:
            value = 2.29
        elif prev in SUPERLATIVES or prev == 'only':
