    elif s == 'such':
        math = bool(re.search(r"[=$\\]|(?<![\w'’])[b-hj-z](?!\w)|\d", history[-50:].lower()))
        value = 0.57 if math else 0.05
        if prev in EXTREMA | SUPERLATIVES:
