        elif prev in {'each', 'any', 'all', 'one', 'some', 'single'}:
            value = 1.8 if math else 0.78
        elif prev in {'number', 'integer', 'integers', 'find', 'be'}:
            value = 1.93
    elif s == 'from' and prev == 'distance':
        value = 0.49
    elif s == 'range' and prev == 'maximum':
