    return (doc, joined[-100:]), value

programs.haiku:
"""Optimisation extremes: the words "maximum", "minimum", "minimal", "minimize" (and the
other max/min/optimise words), and the word right after them, which carries the phrase on:
"the maximum [of]", "the minimal [value]", "the minimal [possible]". Also "such" in
"no such", "all such", and "possible" after a superlative ("largest possible").

Plain-words rules, each with a hand-set level:
  - an extremum word itself: strong (minimize/minimal/maximum...), weak (max/min/sup/inf/optimal)
  - the next word after an extremum word: high if it is of/value/possible/over/such,
    otherwise almost nothing
  - "such" after no/all/any/be: medium; "such" elsewhere: small
  - "possible" after a superlative: high
Everything else predicts 0. Levels are the average activations measured on training rows."""
READS = ()

STRONG = {"maximum", "minimum", "minimal", "maximal", "minimize", "minimise", "maximize",
          "maximise", "minimized", "maximized", "minimizing", "maximizing", "optimization",
          "最小", "最大"}
WEAK = {"max", "min", "sup", "inf", "optimal"}
NEXT_HIGH = {"of", "value", "values", "possible", "over", "such"}
QUANTIFIERS = {"no", "all", "any", "be"}
SUPERLATIVES = {"largest", "smallest", "least", "greatest", "lowest", "highest", "fewest",
                "most", "best", "minimal", "maximal", "maximum", "minimum"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""  # a new document starts here: nothing before it counts

    if word in STRONG:
        return None, 2.0
    if word in WEAK:
        return None, 0.7
    if prev in STRONG or prev in WEAK:
        return None, 3.5 if word in NEXT_HIGH else 0.2
    if word == "such":
        return None, 1.5 if prev in QUANTIFIERS else 0.3
    if word == "possible" and prev in SUPERLATIVES:
        return None, 2.8
    return None, 0.0

programs.sol:
"""SQL clause markers, with a separate document-opening `Title:` response.

SELECT is strongly negative when it starts a query or subquery; mentioning
selection in prose is weakly positive. Nearby SQL syntax distinguishes these
uses. UPDATE ... SET, VALUES, DISTINCT and WHERE have smaller responses.
Inflections of select, ordinary values, and document starts are weakly
positive. Double middle dots have a separate negative response. The carry
keeps only a short text suffix and resets between documents.
"""
import re

READS = ()
SQL = re.compile(r'(?i:sql|query|jdbc|cursor)|\b(SELECT|FROM|JOIN|WHERE|MERGE|USING)\b')
UPDATE = re.compile(
    r'\bupdate\s+(?:[\w.]+|`[^`]+`|"[^"]+")\s*$', re.I
)
STRING = re.compile(r'''[=(]\s*['"`]\s*$''')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, n, previous = '', 0, ''
    else:
        _, tail, n, previous = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    low = word.lower()
    before = tail.rstrip()
    sql = bool(SQL.search(tail))
    value = 0.18 if n == 0 else 0.0

    if word == ':' and n == 1 and previous == 'Title':
        value = 17.63
    elif low == 'select':
        paren = before.endswith('(')
        spaced = s[0].isspace()
        if word == 'SELECT':
            value = -8.7
            if paren:
                value = -11.0 if spaced else -15.0
            elif before.endswith('``'):
                value = -4.5
            elif re.search(r'\bAS$', before):
                value = -11.5
            elif spaced and not sql and before[-1:].isalnum():
                value = -4.5
        elif paren and sql:
            value = -15.0 if word == 'select' else -7.0
        elif word == 'select':
            line_start = not tail.rsplit('\n', 1)[-1].strip()
            if sql and STRING.search(tail):
                value = -8.5
            elif before.lower().endswith('mysql>'):
                value = -7.3
            elif sql and line_start:
                value = -5.0
            elif sql and before.endswith('<tt>'):
                value = -6.0
            elif sql and before.endswith(('import', '=')):
                value = -2.2
            elif before.endswith(('.', '->', '`', '"', "'")) and not spaced:
                value = -1.7
            else:
                value = 0.32 if spaced else -0.4
        else:
            value = 0.3 if spaced else -0.4
            if not spaced and before[-1:].isalnum():
                value = -1.8
    elif word == '.select':
        value = -1.3
    elif low == 'set':
        value = -7.8 if UPDATE.search(tail) else 0.23
        if re.search(r'\bUPDATE\s*$', tail):
            value = -4.8
    elif word == 'VALUES':
        value = -2.8 if not s[0].isspace() else 0.0
        if re.search(r'\b(INSERT|INTO)\b', tail):
            value = -2.6 if before.endswith((')', '`')) else -1.0
    elif low == 'distinct' or (word == 'inct' and before.endswith('dist')):
        value = -0.15
        if re.search(r'\bselect\s*$', tail, re.I):
            value = -6.0
        elif re.search(r'\bcount\s*\(dist?$', tail, re.I):
            value = -4.4
        elif word == 'DISTINCT':
            value = -1.5
    elif low == 'where' and sql:
        value = -0.8 if word == 'WHERE' else -0.65
    elif re.fullmatch(r'select(ed|ing|s|ive(ly)?)', low):
        value = 0.20
    elif low == 'values':
        value = 0.12
    elif s == '··':
        value = -1.2

    return (doc, (tail + s)[-400:], n + 1, s), value

programs.haiku:
"""Quantity versus substance, in recipe, dosing and lab text.

The component is bipolar. It is positive on the words that state an amount or dose
(units such as mg, ml, cup, gram, tablet, dose), on "of"/"with"/"to" right after such a word
("amount of", "ounces of", "treated with"), and on words of adding or taking ("added", "adding").
It is negative on nouns that name an ingredient, composition or material ("ingredients",
"compositions", "cream", "sauce", "onions", "recipe"). Everything else is about zero."""
READS = ()

UNIT = {"mM", "M", "µ", "μ", "µl", "μl", "mg", "ml", "mL", "g", "L", "µg", "μg", "kg", "/ml", "/kg",
        "/L", "/mL", "ounces", "oz", "tablespoons", "tablespoon", "tsp", "teaspoon", "cup", "cups",
        "drops", "gram", "grams", "pounds", "%", "l", "dl", "dose", "tablet"}
AMOUNT = {"amount", "amounts", "dose", "doses", "concentration", "concentrations", "levels",
          "presence", "quantity", "volume", "administration", "addition", "enough", "much", "daily",
          "dosage", "sufficient", "large", "量", "大量的"}
ADD = {"added", "adding", "administered", "administer", "receive", "receiving", "taking", "given",
       "treated", "exposure", "加入", "加", "добав"}
LINK = {"of", "with", "to", "in", "by", "into"}
INGREDIENT = {"ingredients", "ingredient", "compositions", "composition", "compounds", "recipe",
              "cream", "sauce", "cheese", "vegetables", "onions", "onion", "powder", "flour", "sugar",
              "salt", "butter", "milk", "oil", "solvent", "filling", "soup", "pasta"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if cur in UNIT:
        return carry, 0.26
    if cur in LINK and (prev in AMOUNT or prev in ADD or prev in UNIT):
        return carry, 1.0
    if cur in AMOUNT or cur in ADD:
        return carry, 0.4
    if cur in INGREDIENT:
        return carry, -0.45
    return carry, 0.0

programs.sol:
"""Approximate sparse formatting pulses rather than token-specific variation.

Unspaced hash continuations are negative, especially at document start;
a spaced, document-opening hash heading is positive. Repeated markers weaken
line-boundary pulses. Blank separators after thinking tags are negative too.
Small rules cover numeric HTML entities, opening indentation/docstrings, and
middle-dot leaders. Ordinary positions stay near zero.
"""
READS = ()


def opening_value(text):
    if text == '#':
        return 0.372
    if text == '##':
        return 0.978
    if text == '<|im_start|>':
        return 0.396
    if text == r'\t':
        return -2.78
    if text.startswith(('"""', "'''")):
        return -1.8
    if text.isspace():
        return -0.17
    if text.isdigit():
        return -0.124
    if text.isascii() and text.isalpha():
        return 0.013
    return -0.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
        line_start, marker_boundary, markers = True, False, 0
    else:
        _, position, previous, line_start, marker_boundary, markers = carry

    value = -0.002
    if previous == '</think>' and text.isspace():
        value = -0.246
    elif previous == '<think>' and text.isspace():
        value = -0.093
    elif previous.endswith('&#'):
        value = -0.28
    elif previous.strip() in ('#', '##', '###', '//#') and text:
        if position == 1 and previous == '#':
            if text.isspace():
                value = 0.785
            else:
                value = 0.4 if text[0].isspace() else -5.3
        elif not text[0].isspace():
            first = text[0]
            if marker_boundary and first.isascii() and (
                first.isalnum() or first == '-'
            ):
                prominent = first.isupper() or first.isdigit() or first == '-'
                strength = 1.7 if prominent else 0.5
                value = -strength / max(1, markers) ** 0.65
            else:
                value = -0.15 if first.isdigit() else -0.04
        elif previous.strip() == '#':
            value = -0.03
    elif position == 0:
        value = opening_value(text)

    if text and not text.strip('·') and (position == 0 or previous == text):
        value = -0.697
    marker_boundary = line_start or (text.endswith('#') and (
        previous.isspace() or previous.strip('# ') == ''
    ))
    markers += int('#' in text)
    if '\n' in text:
        line_start = not text.rsplit('\n', 1)[-1].strip()
    elif text.strip():
        line_start = False
    return (doc, position + 1, text, line_start, marker_boundary, markers), value

programs.haiku:
"""Layer-1 MLP slot 4471 (down_proj): a sparse feature that responds to document openings,
markup hash signs and chat-template boundaries. It is near 0 almost everywhere, so most of
its variance is small and unexplained; the rules below cover its largest responses.

The rules, in order:
- the first token of a document (the token after <|endoftext|>, or the start of the packed
  row): markup openers such as `<` or `#` push it up (about +0.4); quote, backslash-escape
  and whitespace openers push it down (about -0.4 and -0.15); ordinary words stay near 0;
- a `#` that opens a document, followed by a spaced capitalised word (a markdown heading such
  as "# Title"), pushes it up (about +0.5); the same `#` glued to a word or symbol (a hashtag
  such as "#Sur" or "#*****") pushes it strongly down (about -3);
- a `Title` opening a document followed by `:` pushes it down (about -2.5);
- a `#` used as a hashtag or number sign inside text, followed by a digit or capital
  (`#1`, `#Tag`), pushes it down (about -0.7 for digits, -0.4 for capitals);
- the newline after a closing chat tag `</think>` sits at a steady -0.25;
- a run of middle-dot filler `··` is a constant -0.7.
Everything else is predicted as 0.
"""
READS = ()

def _opener_value(cur):
    if not cur.strip():
        return -0.15
    if cur[0] in '<#':
        return 0.4
    if cur[0] in '\\\'"`':
        return -0.4
    return 0.0

def step(carry, prefix, upstream):
    # carry: 0 if the previous token opened its document, else None
    cur = prefix.token_strings[-1]
    n = len(prefix.token_strings)
    doc = prefix.document_ids
    if n == 1 or doc[-1] != doc[-2]:
        return 0, _opener_value(cur)
    prev = prefix.token_strings[-2]
    if carry == 0:
        if prev == '#':
            if cur[:1] == ' ' and cur[1:2].isupper():
                return None, 0.5
            if cur[:1] != ' ' and cur[:1] != '':
                return None, -3.0
        if prev == 'Title' and cur == ':':
            return None, -2.5
    if prev == '</think>' and cur == '\n\n':
        return None, -0.25
    if cur == '··':
        return None, -0.7
    if prev == '#':
        if cur[:1].isdigit():
            return None, -0.7
        if cur[:1].isupper():
            return None, -0.4
    return None, 0.0

programs.sol:
"""Treat tokens containing at least two newlines as potential block endings.

The response grows after several singly-separated lines, especially lists,
columns, or lines with trailing spaces. Attached punctuation changes the
baseline. Indented blank lines are weaker; reasoning-tag boundaries stronger.
Other tokens receive zero. This deliberately ignores ordinary lexical effects.
"""
import re

READS = ()

BULLET = re.compile(r'\s*(?:[-*+•]\s+|\d+[.)]\s+)')
COLUMNS = re.compile(r'\S[ \t]{2,}\S')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 512, '', '')
    # Consecutive single line breaks, line length, current line, last token.
    _, lines, gap, line, previous = carry
    text = prefix.token_strings[-1].replace('\r', '')
    count = text.count('\n')
    value = 0.0
    if count >= 2:
        before = text.split('\n', 1)[0]
        mark = before.strip()
        whole = line + before
        block = lines > 0
        spaced_inside = (not before and not text.strip()
                         and bool(text.strip('\n')))
        if spaced_inside:
            value = 0.10 if count == 2 else 0.60
        else:
            if not before:
                value = 1.05 if block else 0.36
            elif not mark:
                value = 0.58 if block else 0.03
            elif mark.endswith((',', '，')):
                value = 0.58 if block else -0.03
            elif mark.endswith(('.', '!', '?', '。', '！', '？')):
                value = 0.60 if block else 0.13
            elif mark.endswith((':', '：')):
                value = 0.45 if block else 0.09
            elif mark.endswith(';'):
                value = 0.58 if block else 0.36
            elif mark.endswith((')', ']', '}', '"', "'", '`')):
                value = 0.61 if block else 0.32
            else:
                value = 1.02 if block else 0.33

            bullet = bool(BULLET.match(whole))
            columns = bool(COLUMNS.search(whole)) or whole.lstrip().startswith('|')
            if block:
                value += 0.08 * min(lines, 5)
                value += 0.41 * bullet
                value -= 0.39 * min(max(gap - 24, 0), 100) / 100
                if whole.strip() in ('#', '+', '-'):
                    value += 0.8
            elif ((before and not mark) or mark.endswith(
                    (',', '，', '.', '!', '?', '。', '！', '？', ':', '：'))):
                value += 0.10 * min(gap, 64) / 64
            value += 0.24 * columns
            trailing = bool(whole and whole[-1].isspace() and whole.strip())
            if columns and trailing:
                value += 0.4
            if trailing and (mark or not before):
                value += 0.51
            if count > 2 and not block:
                value += 0.16
            if previous == '<think>':
                value += 0.42
            elif previous == '</think>':
                value += 0.78

    if count:
        lines = min(lines + 1, 5) if count == 1 else 0
        gap = 0
        line = text.rsplit('\n', 1)[1]
    else:
        gap += 1
        line = (line + text)[-500:]
    return (doc, lines, gap, line, text), value

programs.haiku:
"""Announcing what a paper, section or study is about to present, show or do.

Layer-1 MLP unit 4473 writes "I am about to present / show / set out X" into the residual
stream. It is near zero on almost all text and fires on the word where an author says what
the current text (a paper, section, article, study, figure or table) presents:

  * a presentation verb after a self-referring subject: "In this section we [present]",
    "Table 3 [shows]", "FIG. 1 [depicts]", "This paper [describes]", "I will [explain]";
  * the "we" of such a sentence: "In this article, [we] will look at";
  * the "to" of an aim: "The aim of this study is [to] assess ...".

Elsewhere it is small: presentation verbs and "we" without a self-referring context get a
weak 0.3 (e.g. "shows" as a noun, "at present" stay near 0 only when the context is not
academic); everything else is 0.
The first token of each packed row is slightly negative, an edge artifact.
This simple version captures the sparse strong firings; the many small, diffuse values on
ordinary function words are not modelled.
"""

READS = ()

# words that refer to the text itself, or to its author
SELF = {"we", "here", "herein", "paper", "article", "section", "study", "table", "figure",
        "fig", "today", "essay", "chapter", "report", "i"}
# verbs by which a text or author presents, shows or sets out its content
PRESENT_VERBS = {
    "present", "presents", "presented", "show", "shows", "shown", "showing", "describe",
    "describes", "described", "depict", "depicts", "illustrate", "illustrates",
    "illustrated", "outline", "outlines", "outlined", "report", "reports", "reported",
    "demonstrate", "demonstrates", "display", "displays", "summarize", "summarizes",
    "discuss", "explore", "examine", "investigate", "evaluate", "assess", "address",
    "explain", "analyze", "analyse", "review", "introduce", "develop", "propose", "study",
    "list", "lists", "provide", "provides", "focus", "focuses", "look", "consider",
}
AIM_WORDS = {"aim", "aims", "objective", "goal", "purpose", "going"}
STRONG = 1.25  # typical size of a firing on a verb or "we" of a self-referring sentence
WEAK = 0.6  # the "will" and "to" cues, which fire more weakly


def clean(word):
    return word.strip().lower().strip(".,:;()[]\"'")


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0:
        return carry, -0.2
    docs, words = prefix.document_ids, prefix.token_strings
    cur = clean(words[t])
    prev = clean(words[t - 1]) if docs[t - 1] == docs[t] else ""
    # the few words before this one, within the same document
    start = t
    while start > 0 and docs[start - 1] == docs[t] and t - start < 7:
        start -= 1
    near = {clean(w) for w in words[start:t]}
    if cur in PRESENT_VERBS and near & SELF:
        return carry, STRONG
    if cur in PRESENT_VERBS:
        return carry, 0.3
    if cur == "we" and near & SELF:
        return carry, STRONG
    if cur == "we":
        return carry, 0.3
    if cur == "to" and prev in {"is", "was", "are", "were", "going"} and near & AIM_WORDS:
        return carry, STRONG
    if cur == "will" and prev == "we" and near & SELF:
        return carry, WEAK
    return carry, 0.0

programs.sol:
"""Approximate a short, within-word fragment signal.

Track an unbroken run of letters. Small pieces attached to it are positive;
a familiar resulting spelling, an ordinary suffix, or a capitalized piece
reduces the prediction. A drop in spelling frequency raises it. There are
separate corrections for script, partial characters and document starts.
These broad rules deliberately omit individual tokens' idiosyncrasies.
"""
import re
import regex
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
SUFFIXES = set('s es ed ing ly er ers est tion ions ment ments ness ity ities '
               'able ible ful less al ous ive ize ise ation'.split())


@lru_cache(maxsize=100000)
def familiarity(word):
    return max(zipf_frequency(word.lower(), language)
               for language in ('en', 'es', 'fr', 'de', 'pt', 'it'))


@lru_cache(maxsize=10000)
def script(character):
    for name in ('Latin', 'Greek', 'Han', 'Hiragana', 'Katakana'):
        if regex.fullmatch(r'\p{Script=' + name + '}', character):
            return name
    return 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    word = '' if first else carry[1]
    s = prefix.token_strings[-1]
    a = s.lstrip()
    match = re.match(r'[^\W\d_]+', a)
    piece = match.group() if match else ''
    attached = bool(word and s and s[0].isalpha())
    value = -0.004

    if piece and attached:
        kind = script(piece[0])
        if kind in ('Hiragana', 'Katakana'):
            value += 0.038
        elif kind != 'Han':
            n = len(piece)
            old = familiarity(word)
            now = familiarity(word + piece)
            disruption = max(0, old - now - 1) * min(1, 3 / n)
            value += 0.03 if kind in ('Latin', 'Greek') else -0.05
            value += 0.17 / n - 0.0175 * now + 0.031 * disruption
            if piece.lower() in SUFFIXES:
                value -= 0.054
            if piece[0].isupper():
                value -= 0.086

    if first:
        value += 0.14 + 0.15 * bool(piece)
        value += 0.09 * bool(s and not s[0].isspace())
    if '\ufffd' in s:
        value += 0.165
    if a and unicodedata.category(a[0]).startswith('M'):
        value += 0.247

    joined = word + s if s and s[0].isalpha() else s
    ending = re.search(r'[^\W\d_]+$', joined)
    word = ending.group()[-60:] if ending else ''
    return (doc, word), float(value)

"""Approximate a multilingual subword-spelling component.

Strong positives are short Korean -다 endings and Japanese copulas.
Smaller rules cover Greek word fragments, Persian past participles,
Cyrillic да, and Japanese feeling/person words. These are surface-form
rules, not a claim of one shared meaning. Other spellings predict zero.
"""
import unicodedata
import regex

READS = ()

# Inflections of the Japanese plain, polite, and literary copulas.
JAPANESE_COPULAS = {
    'だ': 6.8,
    'です': 2.7,
    'である': 4.5,
    'であ': 4.0,
    'だった': 2.0,
    'だろう': 2.0,
    'だが': 1.9,
    'だけど': 1.2,
    'なんだ': 2.3,
    'んだ': 0.6,
    'でした': 1.3,
    'であり': 1.1,
    'であった': 2.5,
    'であろう': 2.7,
    'ではない': 1.2,
    'のだ': 2.7,
}


def ending_value(token):
    if token in JAPANESE_COPULAS:
        return JAPANESE_COPULAS[token]
    s = token.lstrip()
    if s == '다가':  # Korean connective: while / in the course of
        return 7.0
    if not s.endswith('다'):
        return 0.0
    if s in ('다', '하다'):
        value = 9.5
    elif s == '입니다':  # Polite copula, rather than a polite verb
        value = 4.2
    elif s.endswith('니다'):
        value = 2.7 if len(s) <= 3 else 1.0
    elif s.endswith('겠다'):  # Future / intention
        value = 0.5
    elif s == '마다':  # Distributive particle, not a verb ending
        value = 0.0
    elif len(s) == 2:
        value = 5.4
    else:
        value = 2.3
    if token[:1].isspace():
        value *= 0.8
    return value


KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
HAN_END = regex.compile(r'\p{Script=Han}$')
GREEK_WORD = regex.compile(r'[\p{Script=Greek}\p{M}]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, japanese, tail = (('', 0, b'') if not carry or carry[0] != doc
                                else carry[1:])
    s = prefix.token_strings[-1]
    value = ending_value(s)
    if s == '気':
        # Physical compounds (weather, air, illness, magnetism) differ from
        # mental ones. An honorific お makes the negative response stronger.
        if previous.endswith(('天', '空', '病', '磁')):
            value = 0.0
        elif previous.endswith('お'):
            value = -10.5
        elif HAN_END.search(previous):
            value = -1.6
        else:
            value = -5.0
    elif s == '快':
        if previous.endswith('不'):
            value = -10.5 if japanese else -4.0
        elif japanese:
            value = -5.0
    elif s in ('他', '自己'):
        value = -5.4 if japanese else 0.3  # Others / self in Japanese
    elif s == '皆':
        value = 4.7 if japanese else 1.0  # Everybody
    elif s in ('ν', 'δ', 'ς', 'π'):
        # Greek word beginnings, allowing accents and split UTF-8 characters.
        match = GREEK_WORD.search(tail.decode('utf-8', errors='ignore'))
        word = '' if not match else ''.join(
            c for c in unicodedata.normalize('NFD', match.group())
            if unicodedata.category(c) != 'Mn').casefold()
        if s == 'ν' and word == 'α':
            value = 4.3  # Initial an-
        elif s == 'δ' and word in ('ι', 'ει', 'ανα'):
            value = -4.0
        elif s == 'δ' and word == 'α':
            value = -5.5
        elif s == 'ς' and word in ('τα', 'τη', 'τι', 'ει'):
            value = -1.7  # Short inflected function words
        elif s == 'π' and word in ('α', 'ε'):
            value = -1.4 if word == 'α' else -0.85
    elif s == 'ه':
        # Persian past participles have -ده or -ته.
        value = 0.3
        if previous.endswith(('اد', 'ید')):
            value = -5.5
        elif previous.endswith('د'):
            value = -4.5
        elif previous.endswith('ت'):
            value = -2.3
    elif s == 'ده':
        value = -2.5 if previous.endswith('ر') else -1.0
    elif s == 'اد' and previous == ' د':
        value = -2.6  # داد, the Persian past stem of 'give'
    elif s == ' د':
        value = -1.0
    elif s == ' да':
        value = -1.7  # Cyrillic da (yes / a subordinator)

    japanese = 8 if KANA.search(s) else max(0, japanese - 1)
    tail = (tail + prefix.token_bytes[-1])[-128:]
    return (doc, s, japanese, tail), value

"""Approximate a word-medial nasal-cluster signal, not the usual -ing suffix.

It responds to fragments such as ingo, ingham, inge and inx, and to their
continuations across a token boundary.  Some continuations get extra weight
when the preceding fragment is uncommon in English.  Unmatched positions return
zero, with a small negative baseline at document starts.  Non-Latin spellings
are ignored.  Only the preceding token is remembered; documents reset it.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=131072)
def predict(previous, token):
    p, s = previous.lower(), token.lower()
    value = -0.19 if not previous else 0.0
    q = s if s and s[0] in 'abcdefghijklmnopqrstuvwxyz' else ''

    # Nasal clusters carried within a single token.
    if s.strip().endswith('inge'):
        value += 1.5
    if q.startswith(('ingo', 'ingham')):
        value += 6.2
    if q.endswith('inx'):
        value += 3.5
    if q in ('anga', 'enga', 'ingu'):
        value += 1.3
    if q.startswith(('inged', 'inges')):
        value += 1.2
    if q == 'inja':
        value += 0.5
    if q.startswith('inqu'):
        value += 0.8
    if q == 'nge':
        value += 0.5
    if not q:
        return value

    # The same spellings when the tokenizer splits them up.
    if p.endswith('ary') and q.startswith(('ng', 'nx')):
        value += 7.3 if q.startswith('nge') else 6.0
    elif p.endswith('y') and q.startswith('ng'):
        value += 4.0
    elif p.endswith('yn') and q.startswith('x'):
        value += 4.2
    if p.endswith('nge') and q == 'al':
        value += 4.0

    if p.endswith('ing'):
        rare_stem = (p.strip() != 'ing' and
                     zipf_frequency(p.strip(), 'en') < 3.5)
        first = q[0]
        if first in 'ao':
            value += 6.0 if len(q) == 1 else 0.6 + 1.4 * (len(q) == 2)
            if rare_stem:
                value += 1.5
        elif first in 'iu' and q != 'ing':
            value += 0.9 + 0.7 * (len(q) <= 2)
        elif first == 'h':
            value += 1.1 if p.strip() == 'ing' else 4.5
        elif first == 'e':
            if q == 'ement':
                value += 7.0
            elif q in ('est', 'estion'):
                value += 4.5
            else:
                value += 2.0 if q == 'e' and rare_stem else 0.3
        elif first == 'r' and len(q) > 2 and p.strip() == 'ing':
            value += 6.5 if q == 'ress' else 1.0
    elif p.endswith('in'):
        if q.startswith('g'):
            value += 4.3 if len(q) > 1 else 1.3
        elif q[0] in 'jq':
            value += 1.0
        elif q.startswith('x'):
            value += 0.9
        elif q[0] in 'nmt':
            value -= 0.24
        elif q == 'h':
            value -= 0.2
    elif p.endswith('n') and q.startswith('g'):
        value += 0.4
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), predict(previous, token)

"""Approximate the component with spelling, phrase and formatting rules.

The main positive family is newly joined red/fred/shred-like fragments;
Cyrillic жд also tends positive. German reiz/kreuz/schreib spellings tend
negative. These depend on token boundaries, not just the complete word.
Separate responses cover modal-adverb phrases and initial formatting.
Small, arbitrary lexical fluctuations are deliberately left unexplained.
"""
from functools import lru_cache
import regex as re
from anyascii import anyascii

READS = ()

@lru_cache(16384)
def roman(text):
    return text.lower() if re.search(r'\p{Script=Han}', text) else anyascii(text).lower()

@lru_cache(65536)
def response(previous, token):
    p, s = roman(previous), roman(token)
    value = -0.002
    if token == '··':
        return -2.26
    if p.strip() in ('would', 'could', 'should', 'might'):
        if s.strip() == 'rather':
            value += 7.5
        elif s.strip() in ('otherwise', 'gladly'):
            value += 4.0
    if s.strip().startswith('adher'):
        value -= 3.1 if s.strip() == 'adhere' else 1.1
    if p.endswith('adher') and s.startswith(('ing', 'es', 'ed')):
        value -= 4.0
    if p in ('gerade', 'nahe') and s == 'zu':
        value -= 7.0 if p == 'gerade' else 5.0
    if s.lstrip().startswith('shred'):
        value += 3.0
    if 'fred' in s:
        value += 1.9
    if not (previous[-1:].isalpha() and token[:1].isalpha()):
        return value

    joined, boundary = p[-5:] + s, min(5, len(p))
    def completed(pattern):
        return any(m.start() < boundary < m.end()
                   for m in re.finditer(pattern, joined))

    if s in ('red', 'reds', 'redd') and not token.istitle():
        value += 0.5
        # Different preceding consonants strongly distinguish red fragments.
        for ending, strength in (('d', 7.2), ('g', 5.7), ('sh', 4.6), ('l', 3.2)):
            if p.endswith(ending):
                value += strength
                break
    if s.startswith('fred') and not token.istitle():
        value += 5.1
    if s.startswith('redd'):
        value += 1.8
    if completed(r'fr[ei]{1,2}d'):
        value += 3.3
    if completed('zhd'):
        value += 2.0 if len(s) <= 2 else 0.8
    if p.endswith('ezh') and s.startswith('d') and len(s) <= 2:
        value += 1.0
    if p.endswith('redd'):
        value += 4.5
    elif p.endswith('red'):
        if s in ('t', 'd'):
            value += 3.2
        elif s.startswith(('dy', 'ge')):
            value += 4.8
    if p.endswith('der') and s.startswith('ic'):
        value += 1.7
    if re.search(r'[rр][öøё]$', previous.lower()) and s.startswith('d'):
        value += 2.7

    if re.search(r'\p{Script=Latin}', previous):
        if p.endswith(('re', 'we', 'he')) and s.startswith(('iz', 'uz')):
            value -= 2.5
            if p.endswith('re'):
                value -= 2.5 if s.startswith('iz') else 1.0
        if p.endswith('re') and s.startswith('ib'):
            value -= 3.8 if p.endswith('schre') else 1.6
    if completed(r'r[aeiouy]{0,2}z(?!h)'):
        value -= 0.6
    if s == 'raz':
        value -= 3.2 if p.endswith('d') else 0.8
    if p.endswith('raz'):
        value -= 1.0
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, age, tail = ('', 0, '') if carry is None or carry[0] != doc else carry[1:]
    value = response(tail or previous, token)
    if age == 0:
        value -= 0.126
        if token.startswith(' ') and token.strip() == '.':
            value = -2.59
    if age == 1:
        if previous == '1' and token == '2':
            value = -2.34
        elif previous == 'Title' and token == ':':
            value = 5.63
    # Carry only the unfinished word, including joins spanning three tokens.
    end = re.search(r'\p{L}+$', token)
    new_tail = end.group() if end else ''
    if end and end.start() == 0:
        new_tail = tail + new_tail
    return (doc, token, age + 1, new_tail[-16:]), float(value)

programs.haiku:
"""Fires on pieces of words and names that spell 'red' / 'rid' (Fred, shred, Alfred, Reddit,
integrity), at about +1; Cyrillic д, да, ред at +0.3. Whole words with a leading space
(' red', ' rid') and everything else predict 0.

The component's activation is large and positive on these word-internal pieces and
close to 0 on most text, so this is a sparse 'red/rid spelling' detector.
"""

READS = ()

RED_PIECES = {"red", "fred", "shred", "reds", "redi", "redd", "cred", "alfred", "reddit",
              "ried", "rid", "rick", "rend", "rad", "udge", "ude"}
CYRILLIC_D = {"д", "да", "ред"}


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    if piece[:1].isspace():
        return carry, 0.0
    word = piece.lower()
    if word in RED_PIECES:
        return carry, 1.0
    if word in CYRILLIC_D:
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""A short qu/gu spelling-fragment detector.

The strongest case is a separate u continuing a word-piece ending in g,
particularly a lone u or the sequence ue. Pieces ending in qu/gu also respond;
longer, complete-looking spellings are weaker. A matching previous piece gets
an echo only within the same word. Amplitudes were fitted on training rows.
Token-specific exceptions and sentence-level context are not represented.
"""
import re

READS = ()


def spelling_score(token, previous):
    s, p = token.lower(), previous.lower()
    continuation = bool(token and token[0].isalpha()
                        and previous and previous[-1].isalpha())
    pairs = list(re.finditer(r'[gq][uü]', s))
    trailing = len(s) - pairs[-1].end() if pairs else 99

    # A token ending immediately after the velar consonant plus u.
    if trailing == 0:
        if continuation:
            return 2.72
        return 1.84 if 'gu' in s else 0.51

    # A letter group spanning the token boundary: g + u, ue, ui, ua, ...
    if continuation and p.endswith('g') and s.startswith(('u', 'ü')):
        if len(token.strip()) == 1:
            return 6.31
        if not re.search(r'[uü][aeiou]', s):
            return 0.09
        return 4.97 if re.search(r'[uü]e', s) else 2.46

    # One-token continuation of a fragment just ending in gu or qu.
    if continuation and re.search(r'[gq][uü]$', p):
        return 0.66

    # Short pieces retaining one or two letters after the pair.
    if trailing <= 2:
        if not continuation:
            return 0.07
        if p[-1:] in 'aeiou':
            return 2.22
        return 1.19 if len(token.strip()) <= 4 else 0.37

    if continuation and p.endswith('q') and s.startswith(('u', 'ü')):
        return 2.34
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = spelling_score(token, previous)
    return (doc, token), float(value)

"""Hash-marker detector, with document-start and comment-context corrections.

Single and double hashes give the largest negative response; longer Markdown
heading markers and hashes attached to punctuation give smaller responses.
A document's first marker has the opposite sign. Repeated, deeply indented
hashes look like code comments, rather than new headings. TeX section commands
are another, rarer, heading notation handled here. Other tokens predict zero.
"""
import re

READS = ()
CODE_WORDS = re.compile(
    r'\b(?:def|class|return|import|from|if|else|elif|for|while|try|except|'
    r'print|function|const|let|var|public|private|void|int|using|include|'
    r'endif|define|self)\b'
)


def marker_value(s, text, previous, position, hashes, first):
    count = s.count('#')
    if position == 0:
        if s.strip(' #') == '':
            return {1: 0.60, 2: 2.00, 3: 1.26}.get(count, 0.60)
        return 0.8
    if s.strip(' #') == '':
        line = text.rsplit('\n', 1)[-1]
        indent = len(line) - len(line.lstrip())
        escaped_line = text.endswith('\\n')
        if count == 1:
            if hashes == 0:
                if escaped_line:
                    return -3.46
                if '\n' in previous:
                    return -1.92 if len(CODE_WORDS.findall(text)) >= 2 else -4.28
                return -1.61
            if indent >= 7 and re.search(r'(?:^|\n)\s*#', text):
                return 0.31
            return -2.64 if escaped_line else -1.07
        if count == 2:
            if escaped_line:
                return -3.30
            if previous.count('\n') >= 2:
                return -2.1 if '#' in first else -2.5
            if first.strip().istitle():
                return -1.87
            return -1.44 if s.startswith(' ') else -0.90
        if count == 3:
            return -0.94 if hashes == 0 else -0.70
        return -0.60 if count <= 6 else -0.25
    if '&' in s:
        return -0.20  # HTML numeric character reference
    if '#[' in s:
        return -1.50  # Rust attribute
    if '"' in s or "'" in s:
        return -0.60
    if any(c.isalpha() for c in s):
        return -1.0 if hashes == 0 else -0.30
    return -0.45


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        text, previous, position, hashes, first = '', '', 0, 0, s
    else:
        _, text, previous, position, hashes, first = carry
    value = 0.0
    if '#' in s:
        value = marker_value(s, text, previous, position, hashes, first)
    elif previous == '\\':
        if s == 'section':
            value = -5.5
        elif s == 'subsection':
            value = -1.9
    carry = (doc, (text + s)[-500:], s, position + 1,
             hashes + s.count('#'), first)
    return carry, value
